"""Approximate degree and quality modifiers, mostly with negative activations.

A multilingual degree-word lexicon supplies the basic strengths. Nearby grammar
separates intensification from discourse uses ('rather'), addition ('plus'), and
beauty ('pretty'). Articles complete 'such a/an' and 'quite a/an' constructions.
Some split spellings, token-ending Chinese degree expressions, and Thai markers
are recognized too. Unrecognized cases return zero; document boundaries reset state.
"""
import re
import regex

READS = ()

# Fitted response strengths, grouped by related degree expressions.
DEGREES = (
    (-2.1, 'very quite'),
    (-1.8, 'really completely totally absolutely'),
    (-2.6, 'extremely relatively'),
    (-3.3, 'fairly sufficiently'),
    (-2.3, 'perfectly terribly utterly'),
    (-2.0, 'incredibly remarkably hugely'),
    (-1.5, 'rather pretty wonderfully overly'),
    (-0.9, 'especially particularly slightly entirely somewhat equally'),
    (-0.5, 'highly truly'),
    (-1.3, 'increasingly comparatively excessively'),
    (-2.0, 'exceptionally unusually'),
    (-0.7, 'too'), (-0.25, 'so'), (-0.35, 'such'),
    (-4.5, 'très muy bardzo очень'),
    (-6.0, 'ganz daha'), (-7.0, 'lebih'), (-5.4, 'paling'),
    (-3.4, 'sehr'), (-2.7, 'besonders'),
    (-4.0, 'völlig вполне'), (-3.7, 'recht весьма слишком'),
    (-2.4, 'assez plutôt trop совсем особенно'),
    (-0.8, 'plus noch wirklich'),
    (-4.8, 'более'), (-5.4, 'наиболее'),
    (-4.0, 'самый самым самых'), (-3.1, 'самые'),
    (-2.3, 'самого'), (-1.4, 'самом довольно такой'),
    (-1.25, 'так достаточно'), (-1.6, 'tak'),
    (-3.2, 'så helt'), (-1.8, 'muito molto'), (-2.6, 'molt'), (-2.0, 'troppo'),
    (-2.4, 'bastante tão'), (-2.0, 'çok'),
    (-4.4, 'rất'), (-4.7, 'thật'),
    (-5.7, 'sangat'), (-3.3, 'secara'),
    (-6.8, '더'), (-4.7, '가장'), (-3.4, '더욱'),
    (-2.2, '매우'), (-3.7, '아주'),
    (-3.0, '最も'), (-3.8, 'もっと'), (-2.7, 'より'),
    (-2.4, 'よりも'), (-2.0, 'そんな こんな'),
    (-2.5, 'あまり'), (-1.6, 'かなり'),
)
STRENGTH = {w: value for value, words in DEGREES for w in words.split()}

# Degree expressions can be fused to preceding Chinese words in one token.
CHINESE = {
    '很': -4.4, '最': -4.2, '更': -3.8,
    '更加': -3.8, '比较': -4.2, '比較': -3.5,
    '非常': -3.0, '十分': -3.4, '这么': -4.6, '這麼': -4.4,
    '最为': -5.7, '最為': -5.7, '尤为': -6.5, '尤為': -6.5,
    '极为': -5.0, '極為': -5.0, '太': -2.5,
    '较': -2.4, '較': -3.5, '较为': -3.9, '較為': -3.9,
    '更为': -2.6, '更為': -2.6, '很是': -2.8,
    '相当': -2.4, '相當': -3.4, '如此': -2.1,
    '越来越': -2.5, '越來越': -3.5, '越发': -2.1,
    '极其': -3.9, '極其': -3.9, '无比': -1.8, '無比': -1.8,
    '格外': -2.8, '颇为': -3.5, '頗為': -3.5,
}


COPULAS = set("is are was were be been being am it's it’s i'm i’m that's "
              "we're they're you’re you're isn’t isn't wasn't weren’t".split())
PREDICATORS = COPULAS | set("seem seems seemed look looks looked feel feels felt "
                          "become becomes became sound sounds get gets got getting".split())
ARTICLES = {'a', 'an'}
POSSESSIVES = set("my your his her its our their".split())
PRONOUNS = set("i you he she it we they".split())
SPLIT = {
    'relatively': -6.5, 'très': -7.5, 'более': -8.0, 'muy': -6.5,
    'sehr': -5.4, 'daha': -7.0, 'lebih': -8.0, 'paling': -6.0,
    'очень': -5.3, 'наиболее': -7.8,
    'самое': -5.8, 'самая': -5.8, 'самой': -3.3,
    'ganz': -4.0, 'fairly': -4.3, 'highly': -1.5, 'slightly': -1.8,
    'especially': -0.5, 'completely': -1.0,
    'totally': -1.8, 'absolutely': -1.8, 'particularly': -2.0,
    'woefully': -2.2, 'reasonably': -1.3,
}

# Translations with a degree-bearing adverbial ending.
ROMANCE_DEGREES = {
    'extremamente': -8.0, 'estremamente': -4.5,
    'suficientemente': -8.0, 'particularmente': -3.8,
    'particulièrement': -4.2, 'relativement': -3.8,
    'extrêmement': -5.2, 'praticamente': -3.1,
    'entièrement': -1.4, 'complètement': -2.5,
    'absolument': -1.0, 'tellement': -3.3,
    'particolarmente': -3.8,
}
STRENGTH.update(ROMANCE_DEGREES)
STRENGTH.update({'самое': -5.8, 'самая': -5.8, 'самой': -3.3,
                 '特に': -1.3, 'совершенно': -1.5, 'почти': -1.1,
                 'reasonably': -1.3, 'woefully': -2.2})
SPLIT.update(ROMANCE_DEGREES)


def english_degree(word, last, before):
    """Separate adjective-modifying degree from discourse and noun uses."""
    punct = bool(before) and before[-1] in ',;:(—'
    pred = last in PREDICATORS
    article = last in ARTICLES
    if word in ('particularly', 'especially'):
        if last in ('more', 'most'):
            return 3.2
        if punct or last in ('and', 'but'):
            return -0.1
        return -4.2 if article else -3.3 if pred else -1.4
    if word == 'rather':
        if last in ARTICLES | {'the'}:
            return -5.3
        if pred:
            return -3.5
        return -0.5 if punct or last in ('but', 'would') else -1.3
    if word == 'pretty':
        if last == 'very':
            return 6.0
        if last in ('so', 'too', 'quite', 'really', 'exactly'):
            return 2.5
        if pred:
            return -3.3
        if last in POSSESSIVES | {'the'} or before.endswith(('{', '/')):
            return 1.0
        return -2.3 if article else -1.3
    if word == 'very':
        if last == 'very':
            return 0.9
        if last in POSSESSIVES:
            return 0.0
        if last == 'the' or last in PRONOUNS:
            return -1.0
        if article or last in ('not', "i'm", 'i’m'):
            return -2.8
        if last in ('some', 'all', 'one', 'few', 'still'):
            return -3.7
    if word == 'really':
        if article:
            return -4.2
        if last == 'the':
            return -3.2
        if last == 'only':
            return -0.8
        if last == 'not' or last.endswith(("n't", 'n’t')):
            return -1.0
    if word == 'too':
        if pred:
            return -1.6 if last not in COPULAS else -0.9
        if punct or last in PRONOUNS | {'me', 'him', 'her', 'them'}:
            return -0.2
    if word == 'so':
        if pred:
            return -1.3
        if last == 'not':
            return -0.9
        return -0.03 if punct or last in ('and', 'do') else -0.3
    if word == 'more':
        if article:
            return -2.1
        if last == 'much':
            return -1.1
        return -0.4 if last in ('the', 'little') else 0.05
    if word == 'plus':
        french = re.search(
            r'\b(le|la|les|des|du|une|est|sont|avec|dans|que|qui|il|elle)\b',
            before.lower())
        if last in ('non', 'ne', 'pas'):
            return -0.15
        return -1.6 if french else 0.25
    if word in ('perfectly', 'completely', 'entirely'):
        if last in ('nearly', 'almost'):
            return -0.3
    if word == 'such':
        return -0.1 if punct else -1.8 if last == 'have' else -0.8 if pred else -0.35
    if word == 'highly' and last in ('more', 'most'):
        return 3.5
    return STRENGTH.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    new = (old + prefix.token_bytes[-1])[-240:]
    before = old.decode('utf-8', errors='ignore')
    text = new.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = re.search(r"[\w’']+$", before)
    last = previous[0].lower() if previous else ''
    value = english_degree(word, last, before)

    # A completed, split spelling can differ from a single-token spelling.
    if previous and regex.match(
            r'[\p{Script=Latin}\p{Script=Cyrillic}\p{Script=Hangul}]', token):
        whole = (previous[0] + token).lower()
        if whole in SPLIT:
            value = SPLIT[whole]
        elif word in STRENGTH:
            value = 0.0

    # 'Such a/an' is itself a degree construction.
    if word in ('a', 'an') and last == 'quite':
        value = -2.3
    if word in ('a', 'an') and last == 'such':
        lead = before[:-len(last)].rstrip()
        prior = re.search(r"[\w’']+$", lead)
        prior = prior[0].lower() if prior else ''
        if prior in PREDICATORS | {'have', 'has', 'had', 'with'}:
            value = -5.3
        else:
            value = -2.5 if lead.endswith(('.', ',', ';', ':')) else -3.3
    if token.strip() == 'Recht':
        value = 0.0
    if word == 'tan':
        spanish = re.search(
            r'\b(el|la|los|las|un|una|que|del|es|se|por|con|como)\b',
            before.lower())
        value = -5.8 if spanish else 0.0

    if regex.search(r'\p{Script=Han}$', text):
        for degree, strength in CHINESE.items():
            if text.endswith(degree) and not before.endswith(degree):
                value = strength
                break
    if token[:1].isspace() and word == '最':
        value = -1.8
    if word == '更' and regex.search(r'[\p{Hiragana}\p{Katakana}]', before):
        value = -2.1 if before.endswith(('は', 'も', 'で')) else 0.2
    if word == '太' and before.endswith(('以', '犹', '猶', '亚', '亞', '骨')):
        value = -0.2
    if word in ('那么', '那麼'):
        value = -0.1 if before.endswith(('，', ',', '。', ':', '：')) else -2.8
    # Thai quality nominalization, manner marking, and negation.
    thai = (
        ('ความ', -4.7), ('อย่าง', -5.8), ('ไม่', -2.8),
    )
    for marker, strength in thai:
        if text.endswith(marker) and not before.endswith(marker):
            value = strength
    return (doc, new), float(value)

"""Sparse calendar and administrative-scope detector.

Relative calendar references (especially 'this year') are stronger than
unmodified durations. Chinese administrative labels also fire, particularly
at clause boundaries or in official prose. Han readings are weaker in
Japanese context. Small additional rules cover Korean 해, centered-dot
separators, fullwidth slashes, and document starts. A partial UTF-8
beginning shared with 省 (province) or 县 (county) also fires early, even
when it eventually spells a different character.
"""
import regex as re

READS = ()
ORDINALS = set(
    'first second third fourth fifth sixth seventh eighth ninth tenth'.split()
)
RELATIVE = set(
    'that following previous past coming current preceding prior'.split()
)
# Generic cities, markets and facilities, not administrative place names.
NONADMIN = set(
    ('城市 都市 股市 上市 夜市 超市 房市 社区 社區 小区 景区 园区 '
     '園區 示范区 保护区 服务区').split()
)
# Two-byte beginnings of administrative unit characters.
UNIT_BEGINNINGS = {
    '省'.encode('utf-8')[:2]: 5.2,
    '县'.encode('utf-8')[:2]: 2.3,
}
HAN = re.compile(r'\p{Script=Han}')
KANA = re.compile(r'\p{Script=Hiragana}|\p{Script=Katakana}')
OFFICIAL = re.compile('政府|干部|机关|机构|代表|常委|书记|委员|行政|厅|局|省')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    prior, recent = ('', '') if fresh else carry[1:]
    previous = prior.strip().lower()
    raw = prefix.token_strings[-1]
    text = raw.strip()
    token_bytes = prefix.token_bytes[-1]
    # Recover a character whose earlier bytes occupied preceding tokens.
    if not fresh and len(token_bytes) == 1 and token_bytes[0] >= 128:
        joined = b''.join(prefix.token_bytes[-3:]).decode('utf-8', 'replace')
        if joined and joined[-1] != '\ufffd':
            text = joined[-1]
    word = text.lower()
    boundary = bool(re.search(r'[，。：、；:;\n]\s*$', prior))
    value = 0.0

    if text in {'year', 'month', 'week', 'day'}:
        value = -0.1
        if previous in {'this', 'last', 'next'}:
            if word == 'year':
                value = {'this': 4.6, 'last': 3.7, 'next': 2.3}[previous]
                if previous == 'this' and prior.strip()[0].isupper():
                    value += 0.6
            else:
                value = {'month': 1.4, 'week': 0.6, 'day': 0.1}[word]
        elif previous in ORDINALS or re.fullmatch(r'\d+(st|nd|rd|th)', previous):
            value = 1.9 if word == 'year' else 0.15
        elif previous in RELATIVE or previous in {'each', 'every', 'same'}:
            value = 0.15
            if word == 'year':
                value = 0.5 if previous in {'each', 'every', 'same'} else 0.95
    elif text in {'years', 'months', 'weeks', 'days'}:
        value = 0.25 if previous in RELATIVE | {'these', 'those'} else -0.06
    elif text in {'年', '月', '月份'}:
        value = {'年': 0.6, '月': 1.1, '月份': 0.7}[text]
        value += {'年': 0.3, '月': 0.8, '月份': 0.0}[text] * boundary
    elif re.fullmatch(r'(在)?[今去明]年(以来|以來)?', text):
        value = {'今': 3.1, '去': 3.0, '明': 1.6}[text.lstrip('在')[0]]
        value += 0.6 * boundary
        if text.endswith(('以来', '以來')):
            value += 0.6
    elif re.fullmatch(r'[每本同当當近一两兩多全数數幾几上中下半]+年[来來]?', text):
        value = 1.0 if text.startswith(('近', '全')) else 0.5
    elif text in {'年来', '年來', '年以来', '年以來', '以来', '以來'}:
        value = 1.3
    elif text in NONADMIN:
        value = 0.0
    elif text == '省':
        value = 3.8 + 2.3 * boundary
        if re.search('[本我各该該和与或在]$', prior):
            value += 1.4
    elif re.fullmatch(r'[全本我各该該]省|省[市级級]', text):
        value = 4.0
    elif re.fullmatch(r'[全本我各该該][院校县縣市区區局]|[县縣市][委级級]', text):
        value = 3.5 if text.startswith(('该', '該')) else 2.6
    elif text in {'级', '級'}:
        value = 4.0 if previous in set('省市县縣厅廳部处處科本') else 0.3
    elif re.fullmatch(r'[上各两兩][级級]', text):
        value = 3.3
    elif text.endswith(('县', '縣', '県')):
        value = 1.6 if len(text) == 1 else 0.9
        if text == '県':
            value = 1.0
    elif text.endswith('市'):
        value = 1.2
        if text == '市':
            value += 0.8 * boundary + 1.0 * bool(OFFICIAL.search(recent))
    elif len(text) >= 3 and text.endswith('省'):
        value = 0.9
    elif text.endswith(('区', '區')):
        value = 0.7
    elif text in {'院', '厅', '廳', '局', '校'}:
        value = 1.0 if text != '院' else 0.6
    elif text in {'政府', '法院', '学院', '學院', '学校', '學校'}:
        value = 0.5
    elif text in {'各地', '当地', '當地', '地方', '地區', '地区', '国家', '國家'}:
        value = 0.6
    elif text in {'此次', '本次', '這次', '这次', '上次'}:
        value = 2.3 if text == '此次' else 1.1
    elif text == '해':
        before = '' if fresh else b''.join(prefix.token_bytes[-3:-1]).decode(
            'utf-8', 'replace').strip()
        value = 6.0 if before.endswith(('올', '지난')) else 1.2
    elif text == '／' and re.search(r'\p{Script=Han}$', previous):
        value = -1.6
    elif len(text) >= 2 and set(text) == {'·'} and previous == word:
        value = -1.15

    if HAN.search(text) and KANA.search(recent):
        value *= 0.7
    if not fresh and len(token_bytes) == 1:
        partial = b''.join(prefix.token_bytes[-2:])[-2:]
        if partial in UNIT_BEGINNINGS:
            value = UNIT_BEGINNINGS[partial]
    if fresh:
        if text in {'<|endoftext|>', '<|im_start|>'}:
            value = -3.9 if text == '<|endoftext|>' else -0.27
        else:
            value -= 0.4 if HAN.search(text) else 0.18
    return (doc, raw, (recent + raw)[-60:]), value

"""A documentation-marker detector with an opposite-sign citation response.

Large negatives recognize comment tags, XML documentation, and parameter/type
punctuation. Mentions outside comments are weaker. Citation openings are
positive. Small rules cover .com, Java packages, inline code, and patch/test
markers. The trailing text memory resets at each packed-document boundary.
"""
import re

READS = ()
# Magnitudes for @tag and Doxygen's backslash-tag notation.
TAGS = {
    'param': 14.6, 'return': 8.0, 'returns': 11.1, 'throws': 11.0,
    'var': 5.5, 'type': 5.4, 'property': 4.0, 'see': 1.5,
    'retval': 9.0, 'exception': 8.0,
    'link': 1.3, 'author': 1.0,
}
# XML documentation: (opening tag, closing tag).
XML = {'param': (17.7, 14.5), 'summary': (3.5, 10.3),
       'returns': (11.6, 9.7), 'exception': (9.2, 6.2),
       'typeparam': (12.0, 10.0)}


def response(token, before):
    s, b = token.strip(), before.rstrip()
    line = b.rsplit('\n', 1)[-1]
    comment = b.endswith(('*', '///', '/**'))
    block = b.rfind('/**') > b.rfind('*/')
    tag_line = re.fullmatch(
        r'\s*(?:\d+\s+)?[+-]?\s*(?:\*|///|/\*\*|#)\s*[@\\]*', line
    )
    if s == '@' and b.endswith(';') and '@' in b.rsplit(']', 1)[-1]:
        return 7.0  # Another reference in a bracketed citation.
    if comment and s == '@':
        return -8.0 if token.startswith(' ') else -3.8
    if token.startswith(' ') and s and not s.strip('\\'):
        if comment:
            return -7.3
        if block and not before.rsplit('\n', 1)[-1].strip():
            return -3.7
    tag = s[1:] if s.startswith('@') else s
    if tag in TAGS and (s.startswith('@') or b.endswith('@') or
                       (b.endswith('\\') and (block or tag_line))):
        strength = 1.0 if block or tag_line else 0.4
        if line.lstrip().startswith('#'):
            strength = 0.65
        if b.endswith('\\'):
            strength *= 0.9
        return -TAGS[tag] * strength
    if s in XML:
        strength = 0.2 if s == 'summary' and '///' not in b else 1.0
        if b.endswith('</'):
            return -XML[s][1] * strength
        if b.endswith('<'):
            return -XML[s][0] * strength
    if s == '<' and b.endswith('///'):
        return -6.6
    if s == '</' and '///' in b:
        return -2.1
    if s == 'name' and b.endswith('<param'):
        return -3.0
    if s == '="' and re.search(r'<(?:type)?param(?:ref)? name$', b):
        return -11.5 if b.endswith('<param name') else -7.5
    if s == '="' and b.endswith('<exception cref'):
        return -4.6
    if s in {'$', '{', '}', '>}', '[]}', '{*}', '\\', '\\\\'}:
        typed = re.search(
            r'[@\\]+(param|returns?|var|type|property)\b\s*([^\r\n$]*)$', b
        )
        if typed:
            tag, body = typed[1], typed[2]
            if s == '$':
                return -9.6 if tag == 'param' else -5.0
            if s == '{':
                return -1.0 if tag == 'type' else -3.0
            unclosed = body.count('{') > body.count('}') or s == '{*}'
            if s.endswith('}') and unclosed and '\n' not in token:
                return -5.0 if tag == 'type' else -8.0
            if not s.strip('\\') and not body.strip():
                return -3.5
    if s == ']{' and re.search(r'\\cite[pt]?\[[^\]]*$', b):
        return 6.5
    if s == '{' and re.search(r'\\cite[pt]?$', b):
        return 12.4 if b.endswith('citep') else 10.4
    if s == '[@':
        return 1.8 if token.startswith(' ') else 0.5
    if s == '.com' and re.search(r'@[^@\s.]+$', b):
        return 3.5
    if s == '.com':
        return 0.6
    if s == 'com' and re.search(r'\bpackage$', b):
        return 2.8
    if s == '`' and token.startswith(' '):
        return 0.9 if b.endswith('running') else 0.15
    if s == 'a' and before.endswith('---'):
        return -7.2
    if s == '-' and b.endswith('@@'):
        return 1.9
    if s == '.parametrize' and b.endswith('.mark'):
        return -7.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-220:]), response(token, before)

