"""Documentation-tag detector for one MLP neuron of Qwen3-1.7B (layer 1, down_proj, index 2180).

The neuron is a "doc-comment tag" feature. It goes strongly NEGATIVE on the words that name a
tag in source-code doc comments, and on the marks that open or fill such a tag:
  - Javadoc / PHPDoc:  "* @param", "* @return", "* @throws", "* @var": the "@" that opens the
    tag, then the tag word (param is strongest). On an "@param" line the "$" before the variable
    name and the "}" closing a {type} are also negative.
  - Doxygen:           "* \\param", "* \\return": the backslash that opens it, then the word.
  - XML doc comments:  "/// <param name="x">", "/// </summary>": the "<", the tag word, and the
    '="' after 'name'. A closing "</summary>" is strongly negative, an opening "<summary>" weakly.
  - git diff file headers: the "a" of "--- a/path".
It is POSITIVE on the "{" of a LaTeX citation, as in "\\cite{" or "\\citep{" (about +10).
Everything else predicts 0. Magnitudes are the typical activations measured in training text.
"""
READS = ()

COMMENT_MARKS = {"*", "///", "/**"}
TAG_VALUES = {"param": -15.0, "throws": -12.0, "returns": -10.0, "return": -8.0,
              "summary": -11.0, "exception": -10.0, "var": -6.0, "type": -5.0}
MARKERS = ("@", "\\", "<", "/")


def _line_tokens(prefix):
    """Non-blank tokens before the newest one on its line, in the same document, oldest first."""
    strings, docs = prefix.token_strings, prefix.document_ids
    out = []
    for k in range(len(strings) - 2, -1, -1):
        if docs[k] != docs[-1]:
            break
        s = strings[k]
        escaped_newline = s.strip() == "\\n" or (
            s.strip() == "n" and k > 0 and strings[k - 1].rstrip().endswith("\\"))
        if escaped_newline:
            break                                     # a literal backslash-n also ends a line
        if "\n" in s:
            tail = s.split("\n")[-1].strip()
            if tail:
                out.append(tail)
            break
        if s.strip():
            out.append(s.strip())
    return out[::-1]


def _opens_doc_line(line):
    """True if the line starts with a comment mark (after an optional line number)."""
    words = [x for x in line if not x.isdigit() and x not in ("+", "-")]
    return len(words) >= 1 and words[0] in COMMENT_MARKS


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    line = _line_tokens(prefix)
    p1 = line[-1] if line else ""
    doc = _opens_doc_line(line)
    tag_line = doc and any(x in TAG_VALUES and k > 0 and line[k - 1][-1:] in MARKERS
                           for k, x in enumerate(line))
    value = 0.0
    if tok.startswith("@") and tok[1:] in TAG_VALUES and doc:
        value = TAG_VALUES[tok[1:]]                   # "@param" as one token
    elif doc and tok in TAG_VALUES and p1[-1:] in MARKERS:
        value = TAG_VALUES[tok]                       # the tag word
        if tok == "summary" and p1 == "<":
            value = -3.5                              # opening <summary> is weak
    elif doc and tok in ("@", "\\") and p1 in COMMENT_MARKS:
        value = -7.5                                  # "@" opening a javadoc tag
    elif doc and tok == "<" and line[-1:] == ["///"]:
        value = -5.0                                  # "<" opening an XML doc tag
    elif tok == '="' and doc and p1 == "name" and "param" in line[-3:]:
        value = -10.8                                 # <param name="
    elif tag_line and tok == "$":
        value = -10.0                                 # variable name in an @param line
    elif tag_line and tok == "}":
        value = -5.0                                  # end of a {type} in a tag line
    elif tag_line and tok == "{":
        value = -2.5
    elif tok == "a" and p1 == "---":
        value = -7.5                                  # "--- a/" in a git diff header
    elif tok == "{" and "cite" in p1:
        value = 10.0                                  # \cite{
    return carry, value

