"""A lexical pressure/voltage detector, with secondary code/text cues.

Recognize English pressure and voltage words and the Chinese, Japanese,
Korean and Vietnamese 'press/pressure' roots. Blood, high and low modifiers
strengthen the English response. Character-sized tokens have a larger
response than compounds; UTF-8 fragments are joined before recognition.
Also recognize copyright notices and 'self' in method signatures, rather
than ordinary uses of self. Password words and interpunct separators have
small positive responses. Unmatched tokens receive zero.
"""
import codecs
import re

READS = ()

# Regional spellings of the press/pressure root, with token-scale amplitudes.
PRESS_ROOTS = {'压': 6.8, '壓': 8.9, '圧': 6.2, '押': 4.5, '압': 7.0}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', b'')
    _, before, pending = carry
    raw = prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(pending + raw, 'replace', False)
    rest = (pending + raw)[used:]
    word = text.strip()
    lower = word.lower()
    recent = before.lower()
    value = 0.0

    roots = [ch for ch in word if ch in PRESS_ROOTS]
    if roots:
        if len(word) == 1:
            value = PRESS_ROOTS[roots[-1]] * (1.6 if pending else 1.0)
        elif len(word) == 2:
            value = 2.1 if word[0] in PRESS_ROOTS else 5.0
            if '押' in word:
                value = 0.6  # weaker when this root is merged with another character
            if word[0] == '血':  # blood pressure
                value = 3.7
            elif word[0] in '电電':  # electrical voltage
                value = 4.2
            elif word[0] == '高':  # high pressure
                value = 6.3
        else:
            value = 1.7

    context = recent[:-1] if lower == 'oltage' else recent
    previous_word = re.search(r'([a-z]+)\s*[- ]?$', context)
    modifier = previous_word[1] if previous_word else ''
    if lower.lstrip('-') in ('pressure', 'pressures'):
        value = 1.7 if lower.endswith('pressure') else 1.0
        if modifier == 'blood':
            value += 1.7
        elif modifier in ('high', 'low'):
            value += 1.1
        elif modifier in ('air', 'water', 'gas', 'fluid', 'steam', 'oil'):
            value += 0.9
        elif modifier in ('gauge', 'positive', 'under'):
            value += 0.5
        if lower.startswith('-'):
            value += 1.0
    elif lower in ('voltage', 'voltages', 'oltage'):
        value = 1.7
        if modifier == 'high':
            value = 6.0
        elif modifier == 'low':
            value = 4.5
        elif modifier == 'output':
            value += 0.6
    elif lower == 'ages' and re.search(r'volt$', recent):
        value = 6.0 if re.search(r'high[- ]+volt$', recent) else 3.8
    elif lower == 'volt' and modifier in ('high', 'low'):
        value = 3.0

    joined = recent + lower
    if re.search(r'decompression$', joined):
        value = 2.4
    elif re.search(r'compress(?:ion|ed)?$', joined):
        value = 0.6
    elif lower == 'hydraulic':
        value = 1.0
    elif lower == 'hypertension':
        value = 0.85
    elif lower in ('áp', 'ép'):  # Vietnamese pressure/apply root
        value = 6.4 if lower == 'áp' else 3.5
        if not re.search(r'[ăâđêôơưạ-ỹ]', recent):
            value = 1.6 if lower == 'áp' else 0.0
        if recent.rstrip().endswith('huyết'):
            value = 7.8

    if lower == 'copyright':
        value = 2.5 if word.islower() else 3.2
        if not text[:1].isspace() and word[:1].isupper():
            value = 4.3
        if re.search(r'(?:/\*|\*|//|#)\s*$', before):
            value += 0.2
    elif 'password' in lower:
        value = 0.85 if 'P' in word else 0.6

    if lower in ('self', '(self'):
        signature = before + text
        if re.search(r'\bdef\s+\w+\(\s*self$', signature):
            value = 0.6 if '__init__' in signature else 0.9
        elif re.search(r'\bfn\s+\w+[^()]*\([^)]*self$', signature):
            value = 1.1 if '&mut ' in signature else 0.55

    # A repeated interpunct run, used as a visible separator.
    if word and set(word) == {'·'} and len(word) >= 2:
        value = 0.77
    return (doc, (before + text)[-160:], rest), value

programs.haiku:
"""Pressure, voltage, copyright and password nouns, by their token text.

The component is a lexical detector. It reads the current token and writes a fixed activation
per concept, 0 elsewhere:
  - pressure, the noun in Chinese/Japanese (壓, 压, 高压, 液压, 押, 血压, 压力) and in English
    ("pressure"): strongest for the Chinese characters (about 7), about 2 for the English word;
  - voltage: "voltage" and 电压 (about 2), and "ages" right after "volt" (about 4);
  - Copyright and 版权 (about 3);
  - password words (weak, about 0.65);
  - "self" (weak): "(self" about 0.45, "self" about 0.35.
The values are the least-squares means of each group on training rows. The previous token is
carried only so that "ages" counts after "volt". Verbs and other words like "press",
"impressive" or "suppress" stay near 0.
"""
READS = ()

PRESSURE_STRONG = {"壓", "压", "高压", "液压", "押"}          # pressure, high/hydraulic pressure
PRESSURE_WORDS = {" pressure", "pressure", " Pressure", "Pressure", "-pressure", " pressures",
                  "压力", "壓力", "血压", "压缩"}              # pressure as a noun, English and Chinese
VOLTAGE_WORDS = {" voltage", " Voltage", "电压"}
COPYRIGHT_WORDS = {" Copyright", "Copyright", " copyright", " COPYRIGHT", "\tCopyright", "版权"}
PASSWORD_WORDS = {" password", "password", " Password", "Password", " passwords", " PASSWORD"}


def value(token, previous):
    if token in PRESSURE_STRONG:
        return 7.0
    if token in PRESSURE_WORDS:
        return 2.0
    if token in VOLTAGE_WORDS:
        return 2.2
    if token == "ages" and previous in ("volt", " volt"):
        return 4.0
    if token in COPYRIGHT_WORDS:
        return 3.2
    if token in PASSWORD_WORDS:
        return 0.65
    if token == "(self":
        return 0.45
    if token == "self":
        return 0.35
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    return token, float(value(token, carry))

