SOURCE_OPENERS = {'package', '#include', 'using', 'import', 'from', 'export'}


def opening(token):
    s = token.strip()
    if token == s and s in SOURCE_OPENERS:
        return 1.5
    if token == s and s in {'int', 'def'}:
        return -2.5
    if token.startswith('/*'):
        return 2.0
    if token == '<|im_start|>':
        return 0.5
    if s == '//':
        return -2.1 if '\n' in token else 0.44
    if s == '##':
        return -1.0
    if token[:1].isspace():
        return -0.05
    return 0.28 if token[:1].isupper() else 0.11


def syntax(history, token):
    s = token.strip()
    text = history.replace('\\n', '\n').replace('\\t', '\t')
    escaped = '\\n' in history
