        m = re.search(r'\b(def|func|fun|fn|int|void)\s*$', text)
        if m:
            return -3.1 if m[1] == 'func' and escaped else ENTRY_POINT[m[1]]
        return 0.07
    if s in {'//', '/*'} and not (s == '//' and token.endswith('\n')):
        if re.search(r'(?:^|\n) *\d+\t$', text):
            return -0.1
        line = text.rsplit('\n', 1)[-1]
        indent = len(line) + len(token) - len(token.lstrip(' '))
        if line not in ('', ' ') or indent > 1:
            return -0.025
        blank = bool(re.search(r'\n[ \r]*\n[ \r]*$', text))
        closed = bool(re.search(r'[})];?[ \r]*\n[ \r\n]*$', text))
        go = bool(re.search(
            r'\bfunc\b|:=|\bimport\s*\(|\btype\s+\w+\s+struct|\bmap\[', text))
        if not re.search(r'\bfunction\b|console\.', text):
            go |= bool(re.search(r'\n\treturn [^\n;]+\n\}', text))
        if go and s == '//':
            if blank and token.startswith(' '):
                return -2.9
            if blank:
                return -1.8 if escaped else -8.4
            return -0.3 if escaped else -1.6
        if closed:
            c = re.search(r'\b(void|int|double|float|struct)\b|::', text)
            return (-0.6 if token.startswith(' ') else -0.5) if c else -0.06
        return -0.025
    if s == 'being' and re.search(r'\btheorem\b|proof end', history):
        if re.search(r'\b(for|let)\s+(?:[A-Za-z],\s*)*[A-Za-z]\s*$', history):
