        else:
            value = 1.40 if s.count('\\') == 2 else 0.85
    elif (s.isspace() and '\n' in s and TEX.search(before)
          and re.search(r'\\\\[ \t]*$', before)):
        value = -0.90
    elif s == 'cr' and before.endswith('\\'):
        value = -3.9  # TeX's older row-break command, \cr.
    elif s == ' line' and before.endswith('\",'):
        value = 0.50 if before.endswith('<string>\",') else 1.22
    elif s in ('`', ' `'):
        copied_code = '\u00a0' in before and before.count('`') >= 5
        value = 0.55 if copied_code else 0.0
    elif s and not s.strip('\u00a0'):
        value = -0.27 if len(s) >= 3 else -0.02
    elif s == 'php' and before.endswith('<?'):
        value = 4.247 if position == 1 else 1.62
    elif s == ' com' and before == 'package':
        value = 1.616  # A document-opening Java package declaration.
    elif s == ':' and before == 'Title':
        value = -3.684
    elif s == 'title' and before == '---\n':
        value = 0.71
    elif s == ':' and before == '---\ntitle':
        value = 1.252
    elif len(s) >= 2 and not s.strip('·') and before.endswith('·'):
        value = 2.37
    return (doc, (before+s)[-160:], position+1), float(value)

"""Approximate a response to exposed Germanic spelling fragments.

Strong training examples often expose Hof/Hoff, Horn, Dorf or Holz at a
subword boundary. These rules recognize those and related word/name pieces,
not the meanings of names or German text generally. Strength depends on
where the token cuts the spelling; short endings can continue a response.
Some split h+o spellings and 'though' instead receive negative predictions.
Other positions get a near-zero baseline, with a separate document-start bias.
This is a partial approximation, not an account of every activation.
"""
import re

READS = ()

# German/Dutch word and name elements (hof = court, dorf = village,
# holz = wood, etc.); 'orf' is a shared spelling ending.
# Strength columns: inside this token; cut after the first letter;
# cut later in the preceding token; spanning older tokens; short ending.
PARTS = (
    ('hof', r'h[öo]f+', (6.65, 6.57, 10.34, 3.79, 3.03)),
    ('horn', r'h[öo]rn', (4.58, 6.11, 2.23, 2.48, 1.0)),
    ('dorf', r'dorff?', (2.4, 4.26, 8.22, 8.08, 1.01)),
    ('holz', r'holt?z', (3.0, 5.0, 5.39, 3.21, 1.0)),
    ('horst', r'h[öo]rst', (1.0, 4.0, 4.45, 3.0, 1.0)),
    ('holt', r'holt', (1.87, 3.66, 3.78, 2.0, 1.0)),
    ('hol', r'h[öo]h?l', (1.2, 0.37, 0.31, 0.81, 1.06)),
    ('hafen', r'hafen', (0.5, 2.92, 2.0, 1.0, 0.5)),
    ('hagen', r'hagen', (0.17, 2.45, 2.0, 1.0, 0.5)),
    ('hain', r'hain', (-0.06, 2.29, 2.0, 1.0, 0.5)),
    ('hoven', r'hoven', (0.39, 6.31, 2.0, 1.65, 0.5)),
    ('hout', r'hout', (0.03, 1.09, 1.96, 0.92, 1.23)),
    ('hilf', r'h[iü]lf', (-0.11, 2.0, 3.89, 3.75, 0.5)),
    ('herr', r'herr', (0.71, 1.82, 1.42, 1.0, 0.34)),
    ('haft', r'haft?', (0.44, 1.85, 1.06, 0.75, -0.08)),
    ('hopf', r'h[öo]pf', (1.0, 4.0, 6.29, 2.63, 0.76)),
    ('hirn', r'hirn', (0.0, 2.0, 3.11, 2.71, 0.5)),
    ('orf', r'orf+', (0.77, 2.0, 0.96, 2.0, 0.5)),
)
COMPILED = [(name, re.compile(pattern), weights)
            for name, pattern, weights in PARTS]
LETTERS = re.compile(r'[a-zäöüß]+$')
INFLECTIONS = {'e', 'en', 'er', 'ers', 's', 'es', 'ung'}


def spelling_features(carry, token):
    """Return the unfinished word and a few readable spelling features."""
    old, previous_length = carry
    s = token.lower()
    # Capitalized CamelCase pieces start a new word.
    if token[:1].isupper() and not token.isupper():
        old, previous_length = '', 0
    if not s or not LETTERS.search(s):
        return ('', 0), []
    if not LETTERS.fullmatch(s):
        old, previous_length = '', 0
        s = LETTERS.search(s).group()
    word = (old + s)[-48:]
    boundary = len(word) - len(s)
    previous_start = boundary - previous_length
    if word in {'without', 'throughout'}:
        return (word, len(s)), []
    found = []
    for name, pattern, _ in COMPILED:
        for m in pattern.finditer(word):
            extra = word[m.end():]
            if m.end() <= boundary:
                if m.end() >= previous_start and extra in INFLECTIONS:
                    found.append((name, 4, 1., len(m.group())))
                continue
            if m.start() >= boundary:
                mode = 0                     # element inside this token
            elif boundary - m.start() == 1:
                mode = 1                     # h|of or d|orf
            elif m.start() >= previous_start:
                mode = 2                     # ho|fer or Hol|z
            else:
                mode = 3                     # element spans several tokens
            scale = 1.
            if mode == 0:
                # A recognizable exposed element, not a substring of 'chain'
                # or 'alcohol', or the first letters of 'hold'.
                if m.start() != boundary:
                    if name == 'horn' and word[:m.start()].endswith('t'):
                        scale *= .6
                    else:
                        continue
                if extra:
                    if name == 'horn' and extra == 's':
                        scale *= .6
                    elif name == 'hof' and extra in {'man', 'mann'}:
                        scale *= .15
                    else:
                        continue
            elif extra:
                if extra in INFLECTIONS:
                    scale = 1. if (mode == 2 and extra == 'er') else .65
                    if name == 'horn' and extra == 'e':
                        scale = .25
                    elif name == 'horn' and extra == 's':
                        scale = 1.
                    elif extra == 'ung':
                        scale = .85
                else:
                    continue
            if mode == 1:
                if word[:m.start()].endswith(('c', 'w')):
                    scale *= .2  # ch/wh consonant digraphs
                elif m.start() > 0:
                    scale *= 1.35
            if 'h' in word[:m.start()]:
                scale *= 1.3
            found.append((name, mode, scale, len(m.group())))
    # Nested spellings (hol/holz, orf/dorf) describe one event, not two.
    if found:
        longest = max(x[3] for x in found)
        found = [(name, mode, scale) for name, mode, scale, n in found
                 if n == longest]
    if old.endswith('h') and re.fullmatch(r'o(?:s(?:phere|[oh]?)|us|u|w|d[aeiouy]*)', s):
        found.append(('negative_ho', 0, 1.))
    if s == 'though':
        found.append(('though', 0, 1.))
    return (word, len(s)), found


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        state = ('', 0)
    else:
        state = carry[1]
    state, features = spelling_features(state, prefix.token_strings[-1])
    value = -0.003
    if carry is None or carry[0] != doc:
        value -= .137
    weights = {name: w for name, _, w in PARTS}
    for name, mode, scale in features:
        if name == 'negative_ho':
            value -= 1.21 * scale
        elif name == 'though':
            value -= 0.30 * scale
        else:
            value += weights[name][mode] * scale
    return (doc, state), float(value)

"""Short s-a spelling endings, especially across a token boundary.

Output is normally near zero. It is negative for short sa endings, more
weakly for za, sha, sd and sb. Extra letters following these sequences
rapidly weaken the response. Case, preceding spelling and token spacing
adjust its strength. English frequency adjusts split-token cues. Chinese
name-transcription sa/sha and Japanese kana sa
have separate strengths. An isolated Arabic sin and document starts get
small positive offsets.
This approximates the pattern, not its full word-specific variation.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex
import unicodedata

READS = ()
SA_NAMES = frozenset('萨薩莎')  # Chinese name transcriptions of sa/sha

@lru_cache(maxsize=160000)
def romanize(text):
    # Do not turn unrelated Han characters into English-like syllables.
    text = ''.join('sa' if c in SA_NAMES else
                   '?' if regex.fullmatch(r'\p{Script=Han}', c) else c
                   for c in text)
    return anyascii(text).lower()

@lru_cache(maxsize=160000)
def local(text):
    if text.strip() == 'س':  # The Arabic letter sin without a following vowel
        return .65 if text[:1].isspace() else .45
    han = sum(c in SA_NAMES for c in text)
    if han:
        return -3.49 * han / (1 + .4 * (len(text) - han))
    s = romanize(text)
    whole = s.strip()
    if regex.search(r'\p{Script=Katakana}|\p{Script=Hiragana}|\p{Script=Hangul}', text):
        if whole != 'sa':
            return 0.
        if regex.search(r'\p{Script=Katakana}', text):
            return -1.51
        return -.33 if regex.search(r'\p{Script=Hiragana}', text) else 0.
    space, upper = s[:1].isspace(), text.isupper()
    title = text.strip()[:1].isupper()
    script_scale = 1. if text.isascii() or regex.search(r'\p{Script=Latin}', text) else .3
    value = 0.
    for ending in ('sa', 'za', 'sha', 'sd', 'sb'):
        k = whole.rfind(ending)
        if k < 0:
            continue
        left = whole[:k]
        gain = .18 ** (len(whole) - k - len(ending))
        if ending == 'sa':
            if upper:
                strength = 5.29 * .72 ** k * (.75 if space else 1.)
            elif not left:
                strength = 1.27 if title else .66 if space else 4.33
            else:
                before = left[-1]
                strength = (5.24 if before == 'i' else
                            4.36 if before == 'r' else
                            2.35 if before in 'aeou' else
                            1.78 if before in 'sl' else .42)
                if before not in 'rsl':
                    gain *= .65 ** max(0, k-1)
                if space and not title and k > 1 and before != 'r':
                    gain *= .4
        else:
            strength = {
                'za': .74,
                'sha': .24,
                'sd': 1.45,
                'sb': .8,
            }[ending]
            if upper and ending == 'sd':
                strength = 1.84
            gain *= .55 ** k * (.3 if space and not upper else 1.)
        value -= strength * gain * script_scale
    return value

@lru_cache(maxsize=160000)
def rarity(text):
    text = unicodedata.normalize('NFKC', text.strip())
    return max(0., 5. - zipf_frequency(text, 'en')) / 5.

def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    value = local(text) + (.228 if start else 0.)
    if not start:
        previous = carry[1]
        p, s = romanize(previous), romanize(text)
        if p.endswith(('s','z','x')) and s.startswith(('a','.a','b','d')):
            dotted = s.startswith('.a')
            head = s[1] if dotted else s[0]
            gain = .20 ** (len(s) - (2 if dotted else 1))
            if s == 'as':  # A trailing s weakens the cue less.
                gain = .5
            first = unicodedata.normalize('NFKC', text[1:2] if dotted else text[:1])
            if (head == 'a' and regex.fullmatch(r'\p{Script=Latin}', first)
                    and first not in 'aAáÁäÄ'):
                gain *= .2  # Other accented a's are much weaker cues.
            if head == 'a':
                strength = {
                    's': 3.47,
                    'z': .51,
                    'x': .80,
                }[p[-1]]
                if p.endswith('s'):
                    capital = (previous.strip().isupper()
                               or previous.strip().istitle())
                    strength += 1.93 * capital
                    strength -= .84 * text.isupper() + 2.43 * rarity(previous)
                    # Dotted initials, not dotted member names such as Keys.A.
                    initial = regex.fullmatch(r'[A-Z]?(?:\.[A-Z])+', previous.strip())
                    strength += 3.98 * bool(initial) - 2.06 * dotted
                value -= gain * strength
            elif p.endswith('s'):
                value -= gain * (1.11 if head == 'b' else 1.93)
    return (doc, text), float(value)

"""Formatting and unit-test cues.

The largest negative responses are indentation written after a printed line
number or a literal backslash-n, rather than an actual line break. Positive
responses mark test declarations/calls, web and git prefixes, and title labels.
There are also small rules for module headers, email at-signs, paired dots,
and TeX versus quoted-code backslashes. Other tokens predict zero. Only the
last 200 decoded characters are retained; state resets between documents.
This omits the many small, token-specific background responses.
"""
import math
import re

READS = ()


def predict(s, before, position):
    line = before.rsplit('\n', 1)[-1]
    if s == ':' and position < 5:
        if before == 'Title':
            return 10.56
        if before == '---\ntitle':
            return 3.12
    # Distinguish real indentation from displayed or escaped source code.
    if s and not s.strip(' \t\xa0'):
        n = s.count(' ') + s.count('\xa0')
        tabs = s.count('\t')
        if before.endswith('\\n'):
            return (-0.35 - 0.13 * n if n <= 2 else
                    -0.92 - 0.2 * (1 - math.exp(-(n - 3) / 2)))
        numbered = re.fullmatch(r' *\d+[:| -]?[\t ]*', line)
        if numbered and (tabs or '\t' in line or n >= 4 or
                         any(c in line for c in ':|-') or '\xa0' in s):
            if not tabs:
                return -0.6 - 0.34 * math.log1p(n)
            width = n + 4 * max(0, tabs - 1)
            return -0.83 - (0.28 if width else 0) - 0.33 * math.log1p(width)
        if not s.strip('\xa0') and n >= 3:
            return -0.95
        if not before or before.endswith('\n') or not line.strip():
            if tabs and ' ' in line:
                return -1.3 - 0.2 * math.log1p(tabs)
            return 0.03 - 0.045 * min(n, 8) * bool(tabs) - 0.9 * (' \t' in s)
        if re.fullmatch(r'\s*(?:\+|-|#|//|\*)', line):
            return -0.2 * min(n, 4) - 0.3 * bool(tabs)
        return -0.06 if n > 1 else 0.0
    # Read source code inside quoted strings as code too.
    code = before.replace('\\n', '\n').replace('\\t', '\t')
    word = s.strip(' ./@\t')
    if s == 'TEST' and not code.rsplit('\n', 1)[-1].strip():
        return 2.0
    if word.lower() in ('test', 'tests', 'testmethod'):
        if s.startswith(' ') and re.search(r'\b(?:def|func|function)\s*$', code):
            return 2.4 if word.islower() else 3.15
        if s.startswith(' ') and re.search(r'\b(?:class|fn|void)\s*$', code):
            return 1.7
        if before.endswith(('@', '#[', '[')):
            return 3.05 if before.endswith('#[') else 2.7
        if before.endswith('::'):
            return 0.28 if word.lower() == 'tests' else 1.12
        if s.startswith('/'):
            return 0.2 if word.islower() else 0.9
        if s.startswith('\t'):
            return -0.1
        if word.lower() == 'tests':
            return -0.05 if s.startswith(' ') else 0.4
        if before.endswith('\n') and not s.startswith(' '):
            return 0.55 if word.islower() else 0.28
        if before[-1:].isspace():
            return 0.4 if word.islower() else 0.63
        return 0.05 if s.startswith(' ') and word.islower() else 0.25
    calls = r'\b(?:it|test|describe|suite|context|t\.Run)\s*$'
    if s.lstrip() in ("('", '("', '"') and re.search(calls, code):
        return 2.65 if not s.startswith(' ') else 1.7
    if s.strip() == 'fn' and re.search(r'#\[test\][\s\d]*$', code):
        return 2.0
    if s == '.Run' and code.endswith('t'):
        return 2.3
    if s == '_F' and code.endswith('TEST'):
        return 2.2
    if s == ',' and re.search(r'\bTEST(?:_F|_P)?\([^,\n]+$', code):
        return 2.5
    if s.strip() == 'void' and re.search(r'@Test|\[Test', before[-150:]):
        return 2.7
    if s.strip() == 'void':
        return 0.16
    # Smaller lexical and punctuation responses.
    if s in ('package', 'namespace'):
        if not position and s == 'package':
            return -1.67
        if before.endswith('\n') or not line.strip():
            return 0.4 if s == 'package' else 1.15
        return 0.15
    if s == ';\n\n' and re.match(r'package\b', line):
        return 1.2
    if word == 'git':
        return 0.52 if s.startswith(' ') else 0.72
    if word == 'www':
        return 0.44 if s.startswith(' ') else 1.32
    if s == '@' and before[-1:].isalnum():
        return 1.3
    if s == '··':
        return 0.87
    if s == 'cr' and before.endswith('\\'):
        return 3.1
    if '\\\\' in s and not s.strip(' \\()\'"\n'):
        if s.endswith('\n'):
            return 1.3
        if re.search(r'\\[A-Za-z]+[_{^]', before):
            return 1.4
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, position = '', 0
    else:
        _, before, position = carry
    s = prefix.token_strings[-1]
    value = predict(s, before, position)
    return (doc, (before + s)[-200:], position + 1), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 2191: indentation right after a line number, and test names.

Negative part: source code shown as a numbered listing ("   294<TAB>    code"). The model's
component goes strongly negative on the tab (or the spaces after it) that starts the code on
such a line, more so the deeper the indent.

Positive part: the word "test" and the opening of a test declaration ("def test", "@Test",
"describe('", "it(\"") push the component positive, most strongly on the declaration itself.
Everything else is about zero.
"""
import re

READS = ()
TEST_WORD = {"test", "Test"}
TEST_PIECE = {"/test", ".test", " test", " Test"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[2] != doc:
        line, annot = "", False
    else:
        line, annot = carry[0], carry[1]
    value = 0.0
    word = tok.strip()
    if word == "" and "\n" not in tok:
        if re.fullmatch(r"\s*\d+", line) and "\t" in tok:
            value = -0.9 if tok == "\t" else -(1.4 + 0.03 * tok.count(" "))
        elif re.fullmatch(r"\s*\d+\t[ \t]*", line) and " " in tok:
            value = -1.7
    elif tok in ("('", '("', "(`") and re.search(r"\b(describe|it|test|suite)$", line):
        value = 2.8
    elif word in TEST_WORD and re.search(r"(\bdef|\bfunc|@|\bfn)$", line):
        value = 3.0
    elif tok == " void" and annot:
        value = 3.0
    elif word in TEST_WORD or tok in TEST_PIECE:
        value = 0.35
    if "\n" in tok:
        annot = "@Test" in line + tok
        line = tok.split("\n")[-1]
    else:
        line = line + tok
    return (line, annot, doc), value

programs.sol:
"""A text-pattern approximation: double slashes, URL syntax, and repetition.

Double slashes are strongest in expressions and unfamiliar URL schemes,
weaker as ordinary comments, and weaker still in a run of comments.
The separate Japanese/Thai rules cover iteration signs, small-tsu spelling,
and Japanese -tari/atari spellings. Unrecognized text gets zero; diffuse
low-amplitude and irregular lexical responses are not modeled.
"""
import math
import re

READS = ()


def comment_value(s, previous, tail, count, distance):
    """Classify what immediately precedes a bare // or /// marker."""
    p = previous
    if not p or p == '<|endoftext|>':
        value = -1.8
    elif '\\n' in p or '\\t' in p:
        value = 2.5
    elif p.isspace():
        value = 0.3
        if '\n' in p or '\r' in p:
            value = 0.15
    elif p.endswith(('\n', '\r')):
        value = 0.15
    elif p.strip().endswith(';'):
        value = 0.1
    elif p.strip() in ('}', '{', '},', '],'):
        value = 0.75
    elif p.endswith(')'):
        value = 4.0
    elif p.strip() == ',':
        value = 1.9
    elif '`' in p:
        value = 1.0
    elif p.endswith(('"', "'")):
        value = 2.8
    elif p.endswith(':'):
        value = 5.0
    elif p[-1:].isalnum():
        value = 6.6
        if p in ('n', 't') and tail[:-1].endswith('\\'):
            value -= 1.5
    else:
        value = 2.1
    if re.search(r'\d+[:\-]?\t[ \t]*$', tail):
        value += 1.5
    value += 0.2 * s.startswith(' ')
    value += 0.2 * (s.strip() == '///')
    value += 0.3 * s.endswith('\n')
    value -= 0.19 * math.log1p(count)
    if count:
        value -= 0.4 * math.exp(-distance / 30)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, -10000)
    _, previous, tail, comments, last = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if s.startswith('://'):
        scheme = previous.strip().lower()
        if s == ':///':
            value = 7.0
        elif s != '://':
            value = 7.5
        elif scheme == 'https':
            value = 2.55
        elif scheme == 'http':
            value = 3.0
        elif scheme.endswith(('http', 'https')):
            value = 4.0
        elif scheme in ('ws', 'wss'):
            value = 5.4
        else:
            value = 13.5 if previous else 4.0
    elif s == 'www' and tail.endswith('://'):
        value = -4.8
    elif s == ':/':
        value = 0.65
    elif '//' in s:
        if s.strip() in ('//', '///'):
            value = comment_value(
                s, previous, tail, comments, prefix.position - last)
        elif '"' in s:
            value = 5.5
        elif s.strip() == ')//':
            value = 6.0
        elif len(s) > 8:
            value = -0.3
        comments += 1
        last = prefix.position
    elif s == '々':
        value = 8.3  # Japanese character-repetition sign.
    elif s.strip() == 'ๆ':
        value = 9.5  # Thai word-repetition sign.
    elif s in ('っ', 'ッ'):
        value = 3.3 if s == 'っ' else 1.1
    elif s in ('っと', 'ッと'):
        value = 5.5 if s == 'っと' else 8.0
    elif s in ('たり', 'ったり'):
        value = 1.0 if s == 'たり' else 2.3
    elif s == 'り':
        value = 3.8 if tail.endswith('た') else 0.45
    elif s in ('あたり', '当たり'):
        value = 3.6  # Two spellings of atari (around/per/hit).
    return (doc, s, (tail + s)[-100:], comments, last), value

programs.haiku:
"""Web-address and comment slash detector, with a dip on "www" (layers.1.mlp.down_proj,
component 2192).

What this component does, in plain terms: it responds to the slash tokens that open a web
address or a comment, and it turns that response off, and below zero, on the "www" that
follows "://". It also responds to a few Japanese word fragments.

  * "://" in an address ("https://...") is a strong positive value (about 3).
  * "www" directly after "://" is strongly negative (about -4.8).
  * a "//" right after a URL scheme ("http", "https", ":") is very strong (about 6).
  * a "//" after a number ("LocalSolver 7.0 //") is very strong (about 7); after a
    prose word it is strong (about 3).
  * a "//" that opens a comment after indentation, or after code punctuation (";", "}",
    ")", "`"), is weak (about 0.6 to 0.8).
  * a "//" at the start of a line (a whole-line comment) is about zero or slightly negative.
  * Japanese word fragments: 々 (repeat mark, about 8), っと (5), あたり (4), 当たり (3.6),
    ったり (2.3), っ (3.7), り, たり (about 0.9), ッ (1.1).
Everything else gets 0. The program reads only the current token and the one before it,
so it is causal.
"""

READS = ()

SLASH_TOKENS = {"//", " //", "///", " ///", "//\n", " ///\n", ' "//'}
URL_PREFIXES = ("http", "https", ":")
JP_FRAGMENTS = {
    "々": 8.0, "っと": 5.3, "あたり": 4.4, "当たり": 3.6, "ったり": 2.3,
    "っ": 3.7, "り": 0.9, "たり": 0.9, "ッ": 1.1,
}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    prev = tokens[-2] if len(tokens) > 1 else "\n"
    if cur in JP_FRAGMENTS:
        return carry, JP_FRAGMENTS[cur]
    if cur == "www" and prev == "://":
        return carry, -4.8
    if cur == "://":
        return carry, 2.9
    if cur not in SLASH_TOKENS:
        return carry, 0.0
    if "\n" in prev:
        return carry, -0.4         # whole-line comment
    if prev.strip() == "":
        return carry, 0.6          # comment after indentation
    if "http" in prev or prev.endswith(URL_PREFIXES):
        return carry, 6.0          # double slash of a URL
    if prev.endswith((";", "}", ")", "`")):
        return carry, 0.8          # after code punctuation
    if prev[-1:].isdigit():
        return carry, 6.9          # after a number, e.g. "7.0 //"
    if prev[-1:].isalpha():
        return carry, 3.1          # after a word
    return carry, 1.1


if __name__ == "__main__":
    sample = ["see", " https", "://", "www", ".example", " //", " note", "\n", "//", " code"]

    class _P:
        def __init__(self, toks):
            self.token_strings = toks

    for i in range(len(sample)):
        _, value = step(None, _P(sample[: i + 1]), {})
        print(repr(sample[i]), value)

programs.sol:
"""Approximate a negative spelling-fragment detector, not a topic detector.

The strongest rules recognize short Latin cha/pa/ha pieces. Other rules
recognize a vowel completing ch across a token boundary, with its strength
set by the vowel and how much of the syllable is in the new token. Spaces
separate whole-word beginnings from continuations. Greek and Cyrillic
transliterations use separate rules; short Japanese pa/cha pieces
are also recognized. Unmatched document-initial tokens get a small offset.
"""
import re
import unicodedata
import regex
from anyascii import anyascii

READS = ()


def roman(text):
    return regex.sub(r'[\p{Greek}\p{Cyrillic}]+',
                     lambda m: anyascii(m[0]), text).lower()


def predict(previous, raw, start):
    word = raw.strip().lower()
    gap = bool(raw[:1].isspace())
    latin = all(ch.isascii() or 'LATIN' in unicodedata.name(ch, '')
                for ch in word)
    if latin:
        if re.fullmatch(r'[aeiou]?cha[ns]?', word):
            if not word.startswith('cha'):
                return -1.9
            if len(word) == 3:
                return -2.4 if gap or not previous[-1:].isalpha() else -3.0
            return -0.9 if gap else -1.5
        if re.fullmatch(r'(?:[aeiou]|am)?pas?', word):
            return -0.1 if gap else -1.25
        if not gap:
            if previous[-1:].isalpha() and re.fullmatch(r'(?:[kgp])?han?', word):
                return -0.7
            if re.fullmatch(r'ch[oeiu]s?', word):
                return {'o': -0.75, 'e': -0.25,
                        'i': -0.07, 'u': -0.2}[word[2]]
            if word == 'ch' and raw.strip() != 'Ch':
                return -0.15
    if len(raw) <= 2 and raw[:1] in ('パ', 'ぱ'):
        return -0.5
    if raw in ('ちゃ', 'チャ'):
        return -0.4

    c = ''.join(ch for ch in unicodedata.normalize('NFKD', roman(word))
                if not unicodedata.combining(ch))
    p = roman(previous)
    if not gap and c and c[0] in 'aeiou':
        if previous.strip().lower() == 'χ' and len(c) == 1 and c in 'eio':
            return -0.35
        if p.endswith('ch'):
            if c[0] == 'a':
                if len(c) == 1:
                    return -2.8 if latin else -0.35
                if c[1] == 's':
                    return -1.2 if latin else -0.4
                if len(c) <= 2:
                    return -0.65 if latin else -0.2
                return -0.25 if latin else 0.0
            if c[0] == 'o' and len(c) <= 3:
                if latin and c[1:2] in ('t', 's', 'p', 'k'):
                    return -1.25
                return -0.25
            if latin and c[0] == 'i':
                return -0.1
            if latin and c[0] == 'u' and len(c) <= 2:
                return -0.15
        elif p.endswith(('kh', 'gh', 'ph', 'th')) and c == 'a':
            return -0.9 if latin else -1.4 if p.endswith('kh') else -0.7
        elif p.endswith('kh') and not latin and c == 'o':
            return -1.0
        elif p.endswith('p') and c[0] == 'a' and len(c) <= 2:
            if len(c) == 1:
                return -0.9 if latin else -0.6
            return -0.28 if latin else -0.2
        if previous.strip().lower() in ('π', 'φ', 'θ') and c == 'a':
            return -0.8
    if start:
        return -0.12 if len(word) > 3 and not gap else -0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail = b'' if start else carry[1]
    data = prefix.token_bytes[-1]
    old_text = tail.decode('utf-8', 'ignore')
    joined = (tail + data).decode('utf-8', 'ignore')
    recent = joined[len(old_text):]
    previous = '' if start else prefix.token_strings[-2]
    value = predict(previous, recent, start)
    return (doc, (tail + data)[-12:]), value

programs.haiku:
"""layers.1.mlp.down_proj:2194 -- a 'ch / p / h' name-syllable detector (negative responses).

What it does: this component goes strongly negative on the syllable pieces of rare, multi-piece
names and foreign words that carry a 'ch', 'p' or 'h' sound, and is near zero everywhere else.
The program predicts its activation from the newest token and the word it is building:

- 'cha' pieces (Kich|cha, tor|cha|udio, Hin|cha)       -> about -2
- 'pa' pieces (Sher|pa, Tul|pa, PA in DARPA)           -> about -1.2
- 'ha' pieces (Sule|ha, Dukk|ha)                       -> about -0.7
- a vowel piece right after a piece ending in 'ch'
  (Ch|a, dich|ot, Ch|as, Ch|ona)                       -> about -2
- everything else                                      -> 0

Why these: across the training sample, these pieces carry the component's large negative spikes;
their typical sign and size were consistent between two independent samples of rows. The
program does not model the context that sets the size of each spike, nor the many weaker
negatives on other 'ch' words, so it captures only part of the variance.
"""

READS = ()

CH_PIECES = {"cha", "chan", "acha", "ocha", "chas"}
PA_PIECES = {"pa", "opa", "ipa"}
HA_PIECES = {"ha", "han"}
VOWEL_PIECES_AFTER_CH = {"a", "an", "as", "ot", "ona"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    piece = token.strip().lower()
    inside_word = not token.startswith(" ")
    value = 0.0
    if piece in CH_PIECES:
        value = -2.0
    elif piece in PA_PIECES:
        value = -1.2
    elif piece in HA_PIECES:
        value = -0.7
    if inside_word and len(prefix.token_strings) > 1:
        if piece in VOWEL_PIECES_AFTER_CH and prefix.token_strings[-2].lower().endswith("ch"):
            value = -2.0
    return carry, value

programs.sol:
"""A lone space after indentation is the main positive cue.

Training spikes were dominated by these whitespace boundaries.
The response decreases with document position. Smaller rules cover repeated
tabs and nonbreaking spaces, source-code self/this references, pictographs
(including split UTF-8 tokens), and explicit think delimiters. Other tokens
receive zero. The numeric levels are calibrated on training activations.
"""
import re
import regex
from math import sqrt

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, position, tail = '', '', 0, b''
    else:
        _, previous, recent, position, tail = carry
        position += 1
    value = 0.0
    horizontal = bool(previous) and not previous.strip(' \t')
    if s == ' ':
        if position == 0:
            value = 0.83
        elif horizontal and previous.endswith(' '):
            n = len(previous)
            if n == 1:
                base, boost = 1.23, 0.71
            elif n == 2:
                base, boost = 2.16, 2.12
            elif n == 3:
                base, boost = 2.29, 2.68
            elif n == 4:
                base, boost = 2.43, 1.95
            elif n < 16:
                base, boost = 1.88, 2.18
            else:
                base, boost = 1.67, 1.87
            value = base + boost / sqrt(position)
    elif s == '\xa0' and previous and not previous.strip('\xa0'):
        n = len(previous)
        if n == 1:
            value = 0.4
        elif n == 2:
            value = 1.05
        elif n in {3, 7}:
            value = 2.3
        else:
            value = -0.3
    elif s == '\t' and horizontal:
        n = previous.count('\t')
        if n == 0:
            value = 0.5
        elif n == 1:
            value = 0.8
        elif n == 2:
            value = 1.4
        else:
            value = 1.2
    elif s == '``' and previous and not previous.strip('\xa0'):
        value = 1.4
    elif s == '->' and previous.strip() == 'this':
        value = 1.8
    elif s == '</think>':
        value = 1.0
    elif s == '<think>':
        value = 0.25
    elif s.strip() in {'self', 'this', '(self', '(this'}:
        receiver = s.strip().lstrip('(')
        definition = re.search(r'\b(?:def|fn)\s+\w+\s*\(?[^()]*$', recent)
        operator = re.search(r'[=+*({\[&!:]$', previous.rstrip())
        keyword = previous.strip() in {
            'return', 'yield', 'if', 'while', 'not', 'in', 'await', 'else'
        }
        parameter = definition or previous.strip() in {'mut', '(mut'}
        if receiver == 'self' and parameter:
            value = -0.15
        elif horizontal:
            value = 1.3 if not previous.startswith('\t') else 1.0
        elif operator or (
            keyword and (
                receiver == 'self'
                or previous.strip() in {'return', 'yield', 'await'}
            )
        ):
            value = 1.0
        elif s.startswith('(') or previous.rstrip().endswith(')'):
            value = 0.85
        elif receiver == 'this' and s == 'this' and previous:
            value = 1.0
        elif receiver == 'self' and previous.rstrip().endswith(','):
            value = 0.6
    # Include partial UTF-8 tokens: a pictograph may span several tokens.
    raw = prefix.token_bytes[-1]
    joined = tail + raw
    text = joined.decode('utf-8', 'ignore')
    text = text[len(tail.decode('utf-8', 'ignore')):]
    start = joined.rfind(b'\xf0\x9f')
    if start >= 0 and start + 4 > len(tail):
        if regex.search(r'\p{Regional_Indicator}|\p{Emoji_Modifier}', text):
            value = 1.0
        elif start < len(tail):
            value = 2.4
        elif len(joined) < start + 4:
            value = 1.8
        else:
            value = 0.8 if raw.startswith(b' ') else 2.2
    elif '\ufe0f' in text:
        value = 1.4
    elif regex.search(r'\p{Emoji_Presentation}', text):
        value = 1.4
    return (doc, s, (recent + s)[-160:], position, joined[-3:]), value

programs.haiku:
"""Lone indent-continuation whitespace: fires on the single space (or tab) that
follows a run of spaces (or tabs), i.e. the padding just before a number such as a
line number in a numbered listing. Plus a few small concept rules."""
READS = ()


def _run_of(s, ch):
    return s != "" and set(s) == {ch}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    if tok == " " and _run_of(prev, " "):
        return None, 2.4 if len(prev) > 1 else 1.3
    if tok == "\t" and _run_of(prev, "\t"):
        return None, 1.1
    if tok == "</think>":
        return None, 1.0
    if tok in (" self", "self"):
        return None, 0.7
    if tok == "->" and prev == "this":
        return None, 1.8
    return None, 0.0

"""Object-reference detector for layers.1.mlp.down_proj:2196.

This component fires on the word that refers to the current object in source code, at the
point where the next token will be a member of that object: `self` / `this` (also `$this`,
`(self`, `(this`) used as a receiver in code such as `self.x`, `this.x`, `return this`,
`x = self`. It is near zero when the same words are ordinary English ("this week",
"self-titled"). It also fires on the `->` in PHP's `$this->` (strongest) and on the `::` in
C++ `std::`.

Rules:
- `self`/`this` after a line's indentation, or after code punctuation or keywords such as
  `=`, `(`, `return`, `if`, `$`, `!`, `{`: activation 1.0.
- `this`/`self` after an English word (for example "of this", "in this"): 0.
- `(self`/`(this` as an argument (not in a `def` line): 0.7; in a `def` parameter list: 0.
- `->` right after `this`: 1.5 (PHP `$this->`). `::` right after `std`: 0.8.
- Everything else: 0.

Written as plain rules, no table of token ids.
"""

READS = ()

# Tokens after which `this`/`self` is code (a receiver or an argument), not English prose.
CODE_BEFORE_THIS = {"=", "(", "return", "if", "$", "!", "{", "yield", "elif", "while", "+", "-", "[", ")"}
CODE_BEFORE_SELF = CODE_BEFORE_THIS | {"in", ",", ":", "and", "or", "not", "else", "for"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    cur = raw.strip()
    if prefix.position == 0:
        return None, 0.0
    prev = prefix.token_strings[-2]
    p = prev.strip()
    if cur == "->":
        return None, (1.5 if p == "this" else 0.0)
    if cur == "::":
        return None, (0.8 if p == "std" else 0.0)
    word = raw.lstrip("( \t$")
    if word not in ("self", "this"):
        return None, 0.0
    if raw.lstrip().startswith("("):
        in_def = "def " in prefix.text_prefixes[prefix.position][-200:]
        return None, (0.0 if in_def else 0.7)
    indented = "$" in prev or (p == "" and ("\n" in prev or "\t" in prev or len(prev) >= 2))
    allowed = CODE_BEFORE_SELF if word == "self" else CODE_BEFORE_THIS
    return None, (1.0 if indented or p in allowed else 0.0)

programs.sol:
"""Distance/extension language, with a few visible spelling effects.

Further/farther and German weiter are strongly negative. Degree words
strengthen far; closing 'as' is negative for spatial/size comparisons,
but not idioms such as 'as well as'. Some split f/r word fragments also
respond negatively, while uppercase FA is positive. Everything else is zero.
"""
import re

READS = ()
# Selected degree comparisons, excluding idioms like 'as well as'.
EXTENT = {'early', 'low', 'high', 'small', 'large', 'short', 'big',
          'few', 'strong', 'simple', 'straight', 'fresh'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    low = recent.lower()
    # Treat escaped line breaks like actual line breaks, too.
    text = recent.replace('\\n', '\n').replace('\\r', '\r')
    trailing = re.search(r'([^\W\d_]+)\s*$', text)
    previous = trailing[1].lower() if trailing else ''
    joined = re.search(r'[^\W\d_]+$', text + token)
    assembled = joined[0].lower() if joined else ''
    continuing = bool(token and token[0].isalpha() and recent
                      and recent[-1].isalpha())
    value = 0.0
    if word == 'further':
        value = -4.6 if token.strip()[0].isupper() else -5.15
    elif word == 'farther':
        value = -8.2
    elif word in {'furthest', 'farthest'}:
        value = -6.5
    elif word == 'furthermore':
        value = -2.9 if token.strip()[0].isupper() else -4.3
    elif word == 'far':
        if previous in {'as', 'how', 'too', 'sufficiently'}:
            value = -7.1
        elif previous in {'so', 'thus', 'this', 'that', 'very', 'bit'}:
            value = -4.2
        else:
            value = -1.8
    elif word == 'as':
        if previous in {'far', 'insofar', 'farre'}:
            value = -7.1
        elif (previous in {'north', 'south', 'east', 'west', 'back'}
              and re.search(r'\bas far\b', low[-35:])):
            value = -4.5
        elif previous == 'so':
            value = -1.0
        elif previous in EXTENT and re.search(r'\bas\b', low[-35:]):
            value = -2.6 if previous in {'early', 'low'} else -1.3
    elif word == 'enough' and previous == 'far':
        value = -4.8
    elif word in {'sofar', 'insofar'}:
        value = -5.8
    elif word == 'weiter':
        value = -5.4
    elif word in {'weit', 'weitere'}:
        value = -3.6
    elif '进一步' in word or '進一步' in word:
        value = -2.8
    elif word == 'さらに':
        value = -1.2
    elif word == 'に' and recent.endswith('更'):
        value = -4.5
    elif word == 'moreover':
        value = -1.4 if token.strip()[0].isupper() else -2.1
    elif word == 'father':
        value = -1.1
    elif word == 'fur':
        value = -1.6
    elif token == 'FA':
        value = 6.4 if continuing and recent[-1].isupper() else 2.5
    elif continuing:
        # Completing distance words when the tokenizer splits them.
        if assembled in {'further', 'farther'}:
            value = -10.0
        elif assembled in {'farthest', 'furthest', 'furthers',
                           'soweit', 'verder', 'insofar'}:
            value = -6.5
        elif low.endswith('f') and re.fullmatch('[au]rt?', word):
            value = -2.7 if len(previous) > 1 else -4.8
        # The consonant sequence r+st, split across token boundaries.
        elif low.endswith('r') and word.startswith('st'):
            value = -5.0 if len(previous) == 1 else -2.0
    return (doc, (recent + token)[-64:]), value

programs.haiku:
"""Candidate 5: word-level 'far / further' detector, robust to subword splits,
plus the capital fragment FA (acronyms such as RFA, WFA, NYFA).

The current word is rebuilt from letter-only tokens, so FURT+HER, f+ar, and so+weit
count as one word. The token that completes a distance/extent word gets a negative
value: 'further' about -5, 'as far' / 'too far' / 'how far' about -7.5 (a word after
these degree words), other 'far' about -4.5, and the 'as' that follows 'far' about -7."""
READS = ()

FURTHER_WORDS = {"further": -5.0, "farther": -8.0, "furthermore": -2.5,
                 "weiter": -5.5, "weitere": -4.0}
DEGREE_WORDS = {"as", "too", "how", "so"}
FA_VALUE = 5.5                          # the acronym fragment FA

def word_value(word, prev_word):
    if word in FURTHER_WORDS:
        return FURTHER_WORDS[word]
    if word.endswith("further") or word.endswith("weiter"):
        return -5.0
    if word.endswith("far"):
        return -7.5 if prev_word in DEGREE_WORDS else -4.5
    return 0.0

def step(carry, prefix, upstream):
    word, prev_word = carry if carry is not None else ("", "")
    token = prefix.token_strings[-1]
    if token == "FA":
        return ("", word), FA_VALUE
    if token[:1].isalpha() and not token[:1].isspace():
        word = word + token.lower()           # the word continues
        return (word, prev_word), word_value(word, prev_word)
    stripped = token.strip().lower()
    value = 0.0
    if stripped.isalpha():
        value = word_value(stripped, word)
        if stripped == "as" and word == "far":
            value = -7.0                      # the second 'as' of 'as far as'
        return (stripped, word), value
    return ("", word), value

programs.sol:
"""A spelling-based approximation to Russian short adjectives and participles.

Track the unfinished word.  A short ending such as -ен, -ена or -аны
is more convincing when its corresponding full adjective is a familiar word
(e.g. доступна -> доступный), rather than an accidental noun ending.
Past-tense and infinitive suffixes have a smaller response.  Two common
predicative adjectives, necessary and ready, are also recognized.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Short masculine, feminine, neuter, and plural forms; then partial long forms.
ENDINGS = (
    ('анны', 'long_an'), ('енны', 'long_en'),
    ('енных', 'long_en'), ('енные', 'long_en'), ('енный', 'long_en'),
    ('анный', 'long_an'),
    ('ан', 'an'), ('ана', 'an_vowel'), ('ано', 'an_vowel'), ('аны', 'an_vowel'),
    ('ен', 'en'), ('ена', 'ena'), ('ено', 'eno'), ('ены', 'eny'),
    ('ён', 'en'), ('ёна', 'ena'), ('ёно', 'eno'), ('ёны', 'eny'),
    ('ян', 'yan'), ('яна', 'an_vowel'),
    ('яно', 'an_vowel'), ('яны', 'an_vowel'),
    ('на', 'na'), ('но', 'no'), ('ны', 'ny'),
)
# (weak spelling evidence, dictionary-supported adjective/participle).
STRENGTH = {
    'an': (0.6, 3.7), 'an_vowel': (1.1, 3.3),
    'en': (0.8, 3.5), 'ena': (0.9, 5.9),
    'eno': (1.5, 6.3), 'eny': (2.4, 4.3),
    'yan': (0.8, 0.8), 'na': (0.2, 1.9),
    'no': (0.6, 1.2), 'ny': (0.5, 3.3),
    'long_an': (1.1, 2.5), 'long_en': (0.35, 0.35),
}
PAST = {'ал', 'ала', 'али', 'ало', 'ил', 'ила', 'или', 'ило',
        'ел', 'ела', 'ели', 'ело', 'ла', 'ли', 'лся', 'лась',
        'лись', 'ился', 'илась', 'ились'}


@lru_cache(maxsize=32768)
def adjective_evidence(word):
    forms = [word + end for end in ('ый', 'ий', 'ой', 'ный')]
    if word.endswith(('ен', 'ён')):
        forms.append(word[:-2] + 'ный')
    if word[-1:] in 'аоыи':
        forms.extend(word[:-1] + end for end in ('ый', 'ий', 'ой', 'ный'))
    adjective = max(zipf_frequency(w, 'ru') for w in forms)
    frequency = zipf_frequency(word, 'ru')
    return (
        adjective >= 1.5
        and adjective - frequency >= -1.5
        and frequency >= 0.5
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_word = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    if token.isalpha():
        piece = token.lower()
        word = old_word + piece
    else:
        piece = re.split(r'[^\w]+', token.lower())[-1]
        old_word = ''
        word = piece
    word = word[-64:]
    value = 0.0
    if re.fullmatch('[а-яё]+', word):
        for ending, family in ENDINGS:
            if not word.endswith(ending):
                continue
            # The ordinary -на/-но/-ны shapes also occur in many whole nouns.
            if family in {'na', 'no', 'ny'} and not (
                old_word and piece in {'на', 'но', 'ны'}
            ):
                break
