    (0.47, 'possible potential probable'),
    (0.27, 'relative respective corresponding overall direct indirect net'),
    (0.03, 'actual real complete entire whole absolute necessary fundamental'),
    (0.25, 'major minor significant obvious evident clear explicit visible '
