    -6.0: {"equally", "igual"},
    -3.0: {"similarly", "likewise", "alike", "misma"},
    -2.0: {"gleich", "mesmo", "equal", "equals"},
    -1.2: {"same", "même", "mismo", "similar", "qual"},
    +2.0: {"equity", "equitable"},
}
WORD_VALUE = {w: v for v, words in STRENGTH.items() for w in words}
EQUAL_AFTER = {"an", "of", "with", "and", "or"}

def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings[-4:]]
    word = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if word in ("as", "like") and prev == "just":
        return carry, -6.0
    if word == "way" and prev == "same":
        return carry, -3.5
    if word == "equal" and prev in EQUAL_AFTER:
        return carry, -3.0
    if word == "as" and "same" in toks[:-1]:
        return carry, 1.0
    if word == "to" and prev == "like":
        return carry, 1.5
    return carry, WORD_VALUE.get(word, 0.0)

