    # Only punctuation runs that began at the document's very first token.
    run = s if start else carry
    if run not in ('··', '^^^^') or s != run:
        run = None

    value = initial_value(s) if start else -.0017
    if (not start and s.isascii() and s.isalpha()
            and s.isupper() and len(s) <= 3):
        previous = prefix.token_strings[-2].strip()
        if previous.isascii() and previous.isalpha() and previous.isupper():
            value = .035 if len(s) == 1 else -.011
            value += FIRST.get(s[0], 0.0) + LAST.get(s[-1], 0.0)
    if run:
        value = -2.40 if run == '··' else -2.56
    return run, value

programs.haiku:
"""Accent detector: a negative response to the letter that completes an accented character.

Layer 1's down_proj component 2209 is almost silent on ordinary text. Its large responses are
all on accented letters, most of all Greek vowels carrying a tonos (the acute accent of modern
Greek, as in ά έ ό). Its activation is negative there and is set by how strongly the letter
carries an accent:

- Polytonic Greek with an acute plus a breathing mark (ἔ): about -13.
- Greek vowels with a tonos: έ ά ό about -8, ί ύ about -5, ή ώ about -4.
- Other Greek letters with a diacritic (circumflex, grave, breathing): about -2.
- Latin letters with an acute: ý about -4, ú -1.6, á -1.3, í -0.5, other acutes (é, ó) -0.25.
- Latin ů (ring above): -2.6.
- Plain Greek letters: -0.2. Everything else, including ASCII: 0.

The predicted value is placed on the token that completes the character. Multi-byte characters
are often split across tokens, so the completing token is the last byte piece, and the program
reads the character from the decoded text so far.

Why this is the right concept: the component is a small "accented letter" feature that is
negative and strongest where the diacritic is most distinctive in Greek and Czech/Slovak text.
Its variance is mostly in these letters (about 40% of variance is Greek tonos alone).
"""

import unicodedata

READS = ()

# Accent-carrying combining marks: 0x301 acute, 0x313/0x314 breathing (smooth/rough)
ACUTE, BREATHING = "0x301", ("0x313", "0x314")

# Per-letter strengths, from the component's mean activation on each letter in training text
GREEK_TONOS = {"έ": -8.0, "ά": -8.0, "ό": -8.0, "ί": -5.0, "ύ": -5.0, "ή": -4.0, "ώ": -4.0}
LATIN_ACUTE = {"ý": -4.0, "ú": -1.6, "á": -1.3, "í": -0.5}


def letter_value(ch: str) -> float:
    """The predicted activation for the character `ch` that a token completes."""
    name = unicodedata.name(ch, "")
    marks = {hex(ord(m)) for m in unicodedata.normalize("NFD", ch)[1:]}
    if name.startswith("GREEK"):
        if ACUTE in marks and any(b in marks for b in BREATHING):
            return -13.0  # polytonic, e.g. ἔ
        if ACUTE in marks:
            return GREEK_TONOS.get(ch, -4.0)
        return -2.0 if marks else -0.2
    if name.startswith("LATIN"):
        if ACUTE in marks:
            return LATIN_ACUTE.get(ch, -0.25)
        if ch == "ů":
            return -2.6
    return 0.0


def step(carry, prefix, upstream):
    # Text decoded from the row's start through this token; its last character is the one this
    # token completes, or U+FFFD while a multi-byte character is still incomplete.
    text = prefix.text_prefixes[prefix.position]
    ch = text[-1] if text else ""
    if not ch or ch == "�":
        return None, 0.0
    return None, float(letter_value(ch))

programs.sol:
"""A document-opening response, with special treatment of visual filler.

The usual response is small. At an opening (including an uninterrupted run
of the opening token), it is negative, especially for capitalized Latin
text; declaration keywords, prepositions and negation strengthen it.
Dot leaders, caret marks and horizontal box borders have much larger
responses. A split capitalized Hydro- opening has a positive second piece.
These rules approximate activations, not the component's full computation.
"""
import unicodedata

READS = ()

DECLARATIONS = set("""
package import using namespace class struct interface enum int float double
char bool void var const let def function public private protected static
""".split())
PREPOSITIONS = set("""
of in on at to for from with by into onto over under between through after
before during without within across about
""".split())


def opening_value(token):
    s = token.strip()
    if s and len(set(s)) == 1:
        if s[0] == '·' and len(s) >= 2:
            return -1.03
        if s[0] == '^' and len(s) >= 4:
            return 1.89
        if s[0] == '─' and len(s) >= 4:
            return 1.51
    if token == 'Hy':
        return -0.69
    if token == '<|im_start|>':
        return 0.026
    if not s:
        if '\t' in token:
            return -0.8
        return -0.03 if '\n' in token else 0.08
    if s.isdigit():
        return -0.292
    if any('CYRILLIC' in unicodedata.name(c, '') for c in s):
        return -0.083
    if any('CJK' in unicodedata.name(c, '') for c in s):
        return -0.262
    if s.isalpha():
        value = -0.529 if s.isupper() else -0.469 if s.istitle() else -0.335
        word = s.lower()
        if word in DECLARATIONS:
            value -= 0.6
        if word in PREPOSITIONS:
            value -= 0.2
        if word in {'not', 'no', 'never'}:
            value -= 0.44
        if word in {'this', 'that', 'these', 'those'}:
            value += 0.33
        return value
    if all(unicodedata.category(c)[0] in 'PS' for c in s):
        return -0.186
    return -0.2


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(token)
        return (doc, token, True, 1, value), value
    _, first, repeated, count, initial_value = carry
    repeated = repeated and token == first
    value = initial_value if repeated else 0.002
    if count == 1 and first == 'Hy' and token == 'dro':
        value = 1.415
    return (doc, first, repeated, count + 1, initial_value), value

programs.haiku:
"""Candidate v4: a few concept families of words, plus NUL bytes in UTF-16-style text.

What the component does, as measured on training text:
- NUL bytes: text stored as UTF-16 (or otherwise null-padded) gives a NUL byte between
  every pair of characters. Each NUL after a letter fires strongly (about +1.8); a NUL that
  follows a space fires weakly (about +0.35).
- "Strong" as a word (强, 強, 很强, 较强, 最强): fires positive, about +1 to +2. The compound
  加强 ("strengthen") does not.
- "Problem" (问题, 問題): mildly positive.
- Time and frequency words (现在, 以后, 以前, 经常, 常常, 天天, 至少, 如今) and 学生
  ("student"): negative.
Everything else is near zero, and the common ordinary tokens carry noise of about 0.05.
"""

STRONG = {"强": 1.8, "強": 1.1, "很强": 1.2, "较强": 1.0, "最强": 1.0, "更强": 1.0}
PROBLEM = {"问题": 0.6, "問題": 0.3, "的问题": 0.5, "的問題": 0.3}
TIME_AND_FREQUENCY = {
    "现在": -0.8, "現在": -0.5, "以后": -0.8, "以後": -0.5, "以前": -0.4,
    "经常": -2.0, "經常": -2.0, "常常": -0.9, "天天": -0.7, "至少": -0.7, "如今": -0.4,
}
STUDENT = {"学生": -0.6, "學生": -0.7}

READS = ()

VALUES = {**STRONG, **PROBLEM, **TIME_AND_FREQUENCY, **STUDENT}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "\x00":
        previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
        return None, 0.35 if previous == " " else 1.8
    return None, VALUES.get(token, 0.0)

programs.sol:
"""A sparse response to C-family declarations, especially C# import blocks.

Unspaced `using` and `namespace` at statement boundaries get large negative
values.  Repeated import lines strengthen the response.  C# spelling in the
recent text also strengthens `void` return types and object construction.
Java imports and Visual Basic declarations get smaller negative responses.
Other tokens are left near zero; this does not model the many small lexical
fluctuations in the component.
"""
import re

READS = ()
MODIFIERS = {'public', 'private', 'protected', 'static', 'override', 'internal'}
CSHARP = re.compile(
    r'\busing\s+[A-Z][\w.]*\s*;|\bcsharp\b|C#|'
    r'\bConsole\.|\b(?:string|bool|decimal)\s+\w+|'
    r'\b(?:get|set)\s*;|\b(?:override|readonly|internal|foreach)\b|'
    r'\b(?:Argument(?:OutOfRange|Null)|NotImplemented|InvalidOperation)Exception\b'
)
BASIC = re.compile(r'\bDim\s+\w+|\bEnd\s+(?:Sub|Function|If)|\bAs\s+Variant')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, prev = '', ''
    else:
        _, text, prev = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    # The bounded text buffer is enough for a nearby import/declaration block.
    if prev == '<|endoftext|>':
        text = ''
    next_carry = (doc, (text + token)[-1000:], token)
    if word not in {'using', 'namespace', 'void', 'new', 'System', 'import',
                    'Dim', 'End', 'If', 'Return', 'val'}:
        return next_carry, 0.0
    context = text.rsplit('```', 1)[-1]
    line_start = not context.rsplit('\n', 1)[-1].strip()
    cs = bool(CSHARP.search(context))
    imports = len(re.findall(r'(?:^|\n)\s*using\s+[A-Z][\w.]*\s*;', context))
    explicit_cs = bool(re.search(r'\bcsharp\b|C#', context))
    vb = bool(BASIC.search(context))
    p = prev.strip()
    value = 0.0

    if token == 'using':
        if not text:
            value = -2.36
        elif line_start and imports:
            value = -8.0 if imports == 1 else -9.7
        elif line_start and explicit_cs:
            value = -5.4
        elif line_start:
            value = -0.4
        elif cs and p in {'`', '``'}:
            value = -1.0
    elif word == 'using' and cs and line_start:
        value = -2.0  # resource-management statement rather than import directive
    elif token == 'namespace':
        value = -8.3 if (imports or explicit_cs) and line_start else -0.3
    elif word == 'void':
        if p in MODIFIERS:
            value = -2.7 if cs else -0.55
            if p == 'private':
                value = -3.4 if cs else -2.4
            if p == 'static':
                value = -3.0 if cs else -0.95
            if p == 'override':
                value = -2.5
        else:
            value = -0.35 if line_start else -0.08
    elif word == 'new' and cs and p in {'=', 'return', 'throw', '(', '+=', '=>'}:
        value = -0.65
    elif word == 'System':
        value = -0.85 if p == 'using' else (-0.65 if cs else 0.0)
    elif token == 'import':
        value = -0.48 if not text else (-0.4 if ';' in prev else 0.0)
    elif token == 'Dim' and line_start:
        value = -3.6
    elif vb and word in {'End', 'If', 'Return'} and (line_start or p == 'End'):
        value = -3.0 if p == 'End' else (-1.6 if word == 'End' else -2.0)
    elif token == 'val' and (line_start or p in {';', '{'}):
        value = -0.8

    return next_carry, value

programs.haiku:
"""layers.1.mlp.down_proj:2215 - a "quantity is coming" detector.

What it does: this component fires on the word that opens an amount, a range or a bound,
right before the number, measure or duration it will introduce. Strongest cases:
  - "about" after a preposition ("of about", "at about", "from about"): ~5.6
    (after "is/are": ~1.9; after verbs such as "talk about", "think about": ~0.1)
  - approximators: "approximately", "roughly", "circa", "approx", "nearly", "around",
    "almost", "~", "約", "около" (about 1.5-3.5; "≈" is weaker)
  - ranges: "to" after a number ("2 to", "0 to", ~1.5), "up to" (~2.5), "from" after
    "range/ranging/starting" (~3), a dash after a number ("2-3", ~0.4; en dash "2–3", ~0.7)
  - comparatives of amount: "more than" / "less than" (~2.2), "as few/many/much as" (~2.0),
    "two or three" ("or" after a number, ~1.2)
  - bounds: "at least" (~1.1), "exceed" (~2.2), "few", "only", "just", "over", "more",
    "less", "exactly", "between" (~0.4-0.9)
  - the space token that sits between one of those words and the number after it (~0.6)
Everywhere else it is near zero (a small negative, about -0.3, on the first token after
<|endoftext|>). Values are the average activations measured on training text.

Limits: most of its variance is diffuse small activity on ordinary tokens, which these
word rules do not capture.
"""
READS = ()

# words for an approximate quantity, with typical strength
APPROX = {"approximately": 3.5, "roughly": 3.0, "circa": 3.0, "approx": 2.8, "nearly": 2.8,
          "around": 1.8, "almost": 1.6, "約": 1.9, "约": 1.9, "около": 2.0, "до": 1.9,
          "~": 1.3, "≈": 0.6, "near": 0.7, "≤": 1.0, "≥": 1.0, "<": 0.4, ">": 0.4}
# words that bound or restrict an amount
BOUND = {"exceed": 2.2, "least": 1.1, "few": 0.9, "only": 0.6, "over": 0.6, "just": 0.6,
         "most": 0.6, "below": 0.3, "exactly": 0.5, "more": 0.5, "less": 0.5, "plus": 0.4,
         "between": 0.4, "range": 0.4}
QUANTITY_WORDS = set(APPROX) | set(BOUND) | {"about"}
NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
                "eleven", "twelve", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
                "eighty", "ninety", "hundred", "thousand", "million", "billion", "dozen"}
PREPOSITIONS = {"of", "at", "for", "to", "from", "in", "on", "by", "with", "worth", "than", "over"}
BE_VERBS = {"is", "are", "was", "were", "be", "been", "being"}
TALK_VERBS = {"talk", "talks", "think", "thinking", "know", "learn", "what", "tell", "read",
              "write", "care", "hear", "speak", "talked", "thought", "heard", "knew",
              "information", "details"}


def is_number(s):
    """A digit-initial token or a number word."""
    return s[:1].isdigit() or s in NUMBER_WORDS


def step(carry, prefix, upstream):
    strs = [s.strip().lower() for s in prefix.token_strings]
    w = strs[-1]
    prev = strs[-2] if len(strs) > 1 else ""
    value = 0.0
    if len(strs) > 1 and prefix.token_strings[-2] == "<|endoftext|>":
        value = -0.34
    elif w == "about":
        if prev in PREPOSITIONS:
            value = 5.6
        elif prev in BE_VERBS:
            value = 1.9
        elif prev in TALK_VERBS:
            value = 0.1
        else:
            value = 0.7
    elif w in APPROX:
        value = APPROX[w]
    elif w == "than":
        value = 2.2 if prev in ("more", "less", "fewer") else 0.4
    elif w == "from" and prev in ("range", "ranging", "starting"):
        value = 3.1
    elif w == "to":
        value = 2.5 if prev == "up" else 1.5 if is_number(prev) else 0.0
    elif w in ("-", "–") and is_number(prev):
        value = 0.4 if w == "-" else 0.7
    elif w == "or" and is_number(prev):
        value = 1.2
    elif w == "as" and prev in ("few", "many", "much", "early", "soon"):
        value = 2.0
    elif w in BOUND:
        value = BOUND[w]
    elif w == "" and prev in QUANTITY_WORDS:
        value = 0.6
    elif w == "a" and prev in ("only", "just", "least", "almost", "quite", "over"):
        value = 1.0
    return carry, float(value)

programs.sol:
"""A partial, spelling-based approximation: short o-bearing fragments.

Separate word-initial fragments from continuations. Initial to/fo/lo/ro
families are positive, with article and Romance-language-context suppression.
Internal o, ro and yo depend on the preceding letters, especially t, r and y.
Ro kana, doubled middle dots, and zero after T have separate small rules.
Most tokens receive zero; this does not explain all of the component's signal.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
ARTICLES = frozenset(('a', 'an', 'the'))
FUNCTION_WORDS = ARTICLES | frozenset(('to', 'of', 'in', 'on', 'at'))


@lru_cache(None)
def language_evidence(token):
    word = token.strip().lower()
    if len(word) < 2 or not word.isascii() or not word.isalpha():
        return 0.0
    evidence = zipf_frequency(word, 'en') - max(
        zipf_frequency(word, 'es'), zipf_frequency(word, 'pt'))
    return max(-3.0, min(3.0, evidence))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, english = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    s, p = token.strip().lower(), previous.strip().lower()
    initial = (not previous or token[:1].isspace()
               or not previous[-1:].isalpha())
    tail = p[-1:]
    value = 0.0
    if s.isascii() and s.isalpha() and len(s) <= 4 and 'o' in s:
        if initial:
            if s == 'o':
                value = 0.17 + 0.07 * (english > 0) - 0.24 * (english < -0.3)
            elif len(s) <= 3 and s.startswith(('to', 'fo', 'lo', 'ro')):
                # Exclude the function words and final w/e long-o spellings.
                if s not in ('to', 'for') and not s.endswith(('ow', 'oe')):
                    value = 0.10 - 0.18 * (english < 0) - 0.21 * (p in ARTICLES)
                    value += 0.88 * (s == 'fo') + 0.27 * (s == 'lo')
                    value += 0.20 * (s == 'ro') + 0.26 * s.startswith('to')
                    value += 0.31 * (s == 'ton') + 0.10 * (s == 'too')
                    value -= 0.08 * (s == 'top')
            elif len(s) == 4 and s.startswith('for'):
                value = 0.20 - 0.22 * (p in FUNCTION_WORDS)
            elif s in ('off', 'oft'):
                value = 0.17
        else:
            if s == 'o':
                value = 0.23 * (tail == 't')
                value += 1.09 * (tail == 't' and len(p) <= 2)
                value -= 0.38 * (tail == 'r') + 0.66 * p.endswith('er')
                value -= 1.09 * (tail == 'y') + 0.33 * (tail == 'x')
                value -= 0.16 * (tail == 'h')
            elif s.startswith('o'):
                value = -0.08 * (tail == 'r') - 0.23 * (tail == 'y')
                value += 0.04 * (tail == 't')
                value -= 0.31 * (s == 'op') + 0.21 * (s == 'oc')
                value += 0.03 * (s == 'or')
            if s.endswith('ro'):
                value = -0.06 - 0.34 * (len(s) > 2 and s[-3] in 'aeiou')
                value -= 0.12 * (tail == 't') + 0.45 * (tail == 'y')
                value -= 0.34 * (tail == 'i')
            if s.endswith('yo'):
                value -= 0.64
            if s.endswith('io'):
                value -= 0.03 + 0.20 * (tail == 'r')
            if s in ('mo', 'ho'):
                value -= 0.17
    if token in ('ロ', 'ろ'):
        value = -0.87 - 0.91 * (token == 'ろ')
    if token == '0' and previous.endswith('T'):
        value = 0.37
    if token == '··':
        value = -0.82
    english = 0.9 * english + 0.1 * language_evidence(token)
    return (doc, token, english), float(value)

programs.haiku:
"""Layer 1 MLP unit 2216 (its down_proj column), read as a rule over the current token.

What it does: this unit is quiet almost everywhere. It turns on for a word-initial fragment
(a token with a leading space) that spells the start of "of", "to", "for", "from" or "too",
most of all a lone " o" or " fo" standing in for a split-up word ("the power o f Congress",
"solve fo x"), and it is stronger when the text just before is ordinary English. It also
fires weakly on the bare words " too", " top", " form", " off". It is pushed negative by
pieces that sit inside a longer word (no leading space: "iro", "ero", "aro", "op", "oc",
"yo"), by Japanese kana ("ろ", "ロ", "オ"), and by the horizontal bar "⎯".

The program is a few token lists grouped by that idea, one English-context term, and three
chat-markup tokens. Everything else is predicted as 0.
"""

READS = ()

# Common English words: the share of these among the last WINDOW tokens of the document
# measures how English the text is.
ENGLISH = frozenset(
    "the of and to in is that it for as with on was be by are this from or at an not have "
    "which but has were its he she they we you i a his her their been also more can will one "
    "all there if when who had would about into than them these such some other only what "
    "so do no up out".split()
)
WINDOW = 20

# Word-initial fragments of of/to/for/from-like words; strength rises with English context.
FRAGMENT = {" o", " fo", " lo", " ro", " ol", " ta", " od", " fro", " rom", " ton", " tor",
            " toy", " tom", " tot", " sto", " ford", " fore", " foe", " foc"}
# A few fragments written without a leading space, and "dorf": fixed positive value.
BARE = {"fo", "tol", "dorf"}
# Real words of the same shape: a small steady push.
WORD = {" too", " top", " form", " off", "Too", "Top"}
# Pieces inside a longer word (no leading space), and kana: negative.
INNER = {"ro", "op", "oc", "ero", "iro", "aro", "arro", "yo", "io", "mo", "rio", "eo", "os"}
KANA = {"ろ", "ロ", "オ", "ヨ", "ソ", "⎯"}
# Chat-template markers with a small, steady effect.
MARKERS = {"<think>": 0.2, "<tool_call>": -0.15, "</tool_response>": 0.13}


def english_share(prefix):
    """Share of the last WINDOW tokens, within this document, that are common English words."""
    t = prefix.position
    words = [
        prefix.token_strings[i].strip().lower()
        for i in range(max(0, t - WINDOW), t)
        if prefix.document_ids[i] == prefix.document_ids[t]
    ]
    if not words:
        return 0.0
    return sum(word in ENGLISH for word in words) / len(words)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in FRAGMENT:
        value = 0.05 + 2.8 * english_share(prefix)
    elif token in BARE:
        value = 0.6
    elif token in WORD:
        value = 0.25
    elif token in INNER:
        value = -0.2
    elif token in KANA:
        value = -0.8
    else:
        value = MARKERS.get(token, 0.0)
    return carry, float(value)

programs.sol:
"""Coordination words, especially 'or', plus a document-opening transient.

The positive cue is multilingual but not uniform: some conjunctions are weak
or ambiguous cues. English estimates rise after digits, capitalized words
and -ed endings, and fall for abstract-noun senses in WordNet. At a document's opening,
function words and separating punctuation instead receive negative values.
A repeated opening token retains that opening value until another token occurs.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
AND = frozenset('and und og и і dan và และ'.split())
WEAK_AND = frozenset('et ve és och و'.split())
OR = frozenset('or или eller veya atau hoặc أو'.split())
STRONG_OR = frozenset(('oder', 'ou'))
CHINESE_AND = frozenset(('和', '及', '且', '以及'))
CHINESE_OR = frozenset(('或', '或者'))
RELATIVE = frozenset(
    'who whom whose which what where when why how whether'.split()
)
DEMONSTRATIVE = frozenset('this that these those'.split())
MODAL = frozenset('can could may might must shall should will would'.split())
PRONOUN = frozenset('i you he she it we they'.split())
PREPOSITION = frozenset('of to in for with by from on at into about as'.split())
LINKER = frozenset('but then also however therefore thus otherwise although'.split())
ABSTRACT = frozenset((
    'noun.attribute', 'noun.cognition', 'noun.feeling', 'noun.state',
))


def opening(token):
    word = token.strip()
    low = word.lower()
    spaced = token[:1].isspace()
    if token.startswith('<|'):
        return -5.3 if token == '<|endoftext|>' else 0.0
    if low == 'and':
        return -10.3 if spaced else -7.4
    if low == 'or':
        return -7.7
    if any(c in token for c in ',，、'):
        return -8.8
    if ';' in token or '；' in token:
        return -6.0
    if not word:
        if '\t' in token:
            return -6.7 - 0.08 * len(token)
        if '\n' in token or '\r' in token:
            return -4.0
        return -2.3 - 0.07 * len(token)
    if word.isdigit():
        return -0.9
    if low in RELATIVE or low in LINKER:
        return -6.3 if spaced else -2.0
    if low in DEMONSTRATIVE:
        if spaced:
            return -9.0 if word[:1].isupper() else -5.2
        return -0.5
    if spaced and low in MODAL:
        return -5.3
    if low in PRONOUN:
        return -5.0 if spaced and word[:1].isupper() else -2.2
    if spaced and low == 'the':
        return -6.4 if word[:1].isupper() else -2.3
    if spaced and low in PREPOSITION:
        return -2.8
    if spaced and low in AND | WEAK_AND | OR | STRONG_OR:
        return -5.5
    if not any(c.isalnum() for c in word):
        if all(c in '.·•…' for c in word):
            return -5.3 if len(word) > 1 else -2.9
        if word in ('。', '！', '？'):
            return -5.0
        if any(c in word for c in '\'"'):
            return -3.5
        return -1.5
    return -1.7 if spaced else (-0.3 if word[:1].isupper() else -0.7)


@lru_cache(maxsize=4096)
def lexical_adjustment(word):
    low = word.lower()
    pos = wordnet.parts_of_speech(low)
    cats = wordnet.categories(low)
    value = -0.06 * ('noun' in pos) + 0.07 * ('adjective' in pos)
    value += 0.12 * ('adverb' in pos)
    value -= 0.1 * len(ABSTRACT.intersection(cats))
    value -= 0.05 * (len(word) >= 6)
    value += 0.25 * low.endswith('ed')
    value -= 0.08 * low.endswith((
