"""Layer-1 MLP down_proj, hidden unit 2217: a coordinating-conjunction detector, plus a
document-start signal.

1. Inside a document, the unit is positive on coordinating conjunctions and their
   translations. "or" is strongest (about +1.0: or, oder, ou, или, eller, 或), "and" next
   (about +0.6: and, und, og, och, и, và, dan), and a few weak ones (et, y, e, ve, 和) are
   about +0.2. Everything else is about 0.
2. At the first token of each document (positions reset there), the unit is strongly
   negative when that token cannot open a text. Commas and semicolons (about -9), and
   conjunctions such as "and", "or", "which", "then" (about -8), go most negative. Prepositions
   and determiners ("with", "to", "of", "the") are about -2.6, other punctuation about -2,
   other lowercase or capitalised words about -1.5, digits about -0.9, and auxiliary verbs
   and capitalised starts about -0.3 to -0.5.
"""

READS = ()

OR_WORDS = {" or", " Or", " OR", "Or", "/or", " oder", " ou", " или", " eller", " 或", "或者", "或"}
AND_WORDS = {" and", " And", " AND", "And", "and", " und", " og", " och", " и", " và", " és", " dan", " و"}
WEAK_WORDS = {" et", " y", " e", " ve", "和", " 及", " &"}
JOIN_MARKS = set(",;，；")
CONJUNCTION_WORDS = {"and", "or", "but", "nor", "which", "that", "then", "when", "while", "because", "if", "so", "yet"}
PREPOSITION_WORDS = {"by", "with", "to", "of", "for", "the", "in", "on", "it", "you", "this", "a", "all", "from", "at", "as", "an", "he", "she", "they", "we", "i"}
AUXILIARY_WORDS = {"is", "are", "was", "were", "be", "been", "have", "has", "not", "can", "will", "would", "should", "do", "does", "did", "am"}


CODE_STARTS = {"#", "#include", "//", "/*", "int", "INT", "string", "char", "var", "class"}


def document_start_value(token):
    text = token.strip()
    word = text.lower()
    spaced = token.startswith(" ")
    if token.startswith("<|"):
        return 0.0
    if token in CODE_STARTS or text.startswith("//") or text.startswith("#"):
        return 2.0
    if text and all(c in JOIN_MARKS for c in text):
        return -8.7
    if text == "" or not any(c.isalnum() for c in text):
        return -2.0
    if text.isdigit():
        return -0.9
    if spaced and word in CONJUNCTION_WORDS:
        return -7.8
    if spaced and word in PREPOSITION_WORDS:
        return -2.6
    if spaced and word in AUXILIARY_WORDS:
        return -0.4
    if spaced:
        return -1.6
    if text[:1].isupper():
        return -0.3
    return -0.8


def conjunction_value(token):
    if token in OR_WORDS:
        return 1.0
    if token in AND_WORDS:
        return 0.6
    if token in WEAK_WORDS:
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    starts_document = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_document:
        return None, document_start_value(token)
    return None, conjunction_value(token)

