"""Approximate a signed spelling-pattern response at word-fragment joins.

Base scores favor vowel-rich ``li`` spellings and oppose ``mi`` joins and
some short m-vowel fragments. Fragment length and ordinary
English inflectional endings adjust the response. Other tokens stay near zero.
Only adjacent token spellings are used, with accents folded to base letters.
"""
import unicodedata

READS = ()
VOWELS = "aeiou"
L_BEFORE_I = {
    "a": 2.497,
    "e": 1.7,
    "o": 2.925,
    "u": 3.45,
}
M_BEFORE_I = {
    "a": -2.487,
    "e": -0.51,
    "o": -0.979,
    "u": -1.403,
}


def fold(text):
    return "".join(c for c in unicodedata.normalize("NFKD", text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    baseline = 0.001
    if (prefix.position == 0 or
            prefix.document_ids[-1] != prefix.document_ids[-2]):
        return None, baseline
    previous, current = prefix.token_strings[-2:]
    if not (previous and current and previous[-1].isalpha() and current[0].isalpha()):
        return None, baseline
    previous, current = fold(previous), fold(current)
    score = 0.0

    # A boundary between l/m and i followed by another vowel.
    iv = len(current) > 1 and current[0] == "i" and current[1] in "aeou"
    if iv:
        if previous.endswith("l"):
            score += L_BEFORE_I[current[1]]
            if len(current) > 4:
                score -= 1.132
        elif "l" in previous[-3:]:
            score += 0.578
        if previous.endswith("m"):
            score += M_BEFORE_I[current[1]]
            if len(previous.strip()) > 4:
                score += 1.181
        elif "m" in previous[-3:]:
            score -= 0.398

    # Follow li inside this fragment or at the previous fragment's end.
    if "li" in current[:4]:
        score += 0.09
    if any("li" + v in current[:5] for v in VOWELS):
        score += 2.423 if len(current) <= 4 else 0.236
    if previous.endswith("li") and current[0] in VOWELS:
        score += 1.075
        if current[0] == "o":
            score += 1.167
    if previous.endswith("g") and current.startswith("li"):
        score += 0.262

    if previous.endswith("l") and current.startswith("i"):
        if len(current) == 1:
            score += 0.528
        if current.startswith(("ing", "ies", "ied")):
            score -= 0.268

    # Negative response to short m-vowel continuations.
    if current.startswith("mo"):
        score -= 0.144
        if previous.endswith("s"):
            score -= 1.245
    if (len(current) == 3 and current[0] == "m" and current[1] in VOWELS
            and current[2] in "lrmn"):
        score -= 0.239
    return None, baseline + score

"""Text rules for escapes and quantifier constructions, learned from training.

Doubled backslashes are positive in escaped text, but negative as TeX row
breaks. Frequent nested quote escaping weakens the positive response. Other
rules cover line-initial 1 (weaker after recent ones), digit 5 in numbers and
technical names, English/Chinese quantifiers and split indefinite pronouns.
Two literal fragments, Thai หน and doubled middle dots, have additional rules.
Unmatched tokens get zero. The 256-character history resets at each document.
This approximates selected patterns, not all of the component's variation.
"""
import re

READS = ()

TEX = re.compile(
    r'(?<!\\)\\(?:begin|end|[dt]?frac|left|right|math\w*|text\w*|'
    r'over|q?quad|hline|cr|lim|rightarrow|alpha|beta|delta|sigma|tau|'
    r'phi|ell|nabla|partial|overline|hat|dagger|sum|pmatrix|mbox|'
    r'hfill|bbx|xspace)\b'
)
QUANTIFIERS = {'each', 'every', 'any', 'which', 'either', 'another'}


def response(text, before, first):
    word = text.strip()
    lower = word.lower()
    if '\\\\' in text:
        math = bool(TEX.search(before[-240:]))
        if math and not re.search(r'\\[nt](?![A-Za-z])|\\["\']', before[-100:]):
            return -2.4  # TeX row break
        if text.startswith(('(\'', '("')):
            return 1.5  # quoted escape opener
        if before.endswith(('\\"', "\\'")):
            return 1.6  # escape after escaped quote
        if '\n' in text:
            return -2.4  # TeX row break
        if before[-160:].count('\\'*3 + '"') >= 5:
            return 0.55  # frequent nested quote escaping
        return 1.05  # literal escaped backslash
    if before.endswith('\\\\') and text == '\\"':
        return 0.6  # multiply escaped quote
    if before.endswith('\\') and lower == 'cr':
        return -4.6  # TeX carriage return
    if lower in {
        'newline', 'non', 'h', 'line'
    } and re.search(r'\\(?:h|tabular)?$', before):
        return -1.3  # TeX line command
    if before.endswith('\\') and lower == 'display':
        return 0.2  # TeX display command
    if word == '1':
        if first:
            return -0.47  # initial one
        line = before.rsplit('\n', 1)[-1]
        if not line.strip() and '\n' in before:
            earlier = before.rstrip()
            if earlier.endswith((':', '：')):
                return (-0.77 if '1' not in before
                        else -0.52)
            if before.count('1') >= 3:
                return -0.085  # continued line one
            if '1' in before:
                return -0.24  # previously seen line one
            return -0.48  # line initial one
        if before.endswith(('\\n', '\\n\\n')):
            return -0.48  # line initial one
        return -0.005  # other one digit
    if word == '5':
        if re.search(r'(?:md|hdf|html|pyqt|perl)$', before, re.I):
            return -1.3  # technical five
        if before.endswith('6'):
            return -0.28  # decimal prefix 65
        if before and before[-1].isalpha():
            return -0.35  # identifier five
        if before.endswith('.'):
            return 0.09  # decimal five
        return -0.057  # other five
    if lower in {'one', 'of', 'body', 'thing'}:
        previous = re.findall(r'[A-Za-z]+', before[-45:])
        prev = previous[-1].lower() if previous else ''
    if lower == 'one':
        if prev == 'some':
            return -1.3  # some one
        if prev == 'which':
            return 0.85  # interrogative one
        if prev == 'every':
            return -0.38  # every one
        if prev == 'each':
            return 0.4  # each one
        if prev in QUANTIFIERS:
            return 0.2  # quantified one
    if lower == 'of':
        if prev == 'one':
            words = [x.lower() for x in previous]
            if len(words) > 1 and words[-2] in QUANTIFIERS | {'single', 'last'}:
                return 1.7  # quantified one of
            return -0.015  # one of
        if prev == 'amount':
            prior = previous[-2].lower() if len(previous) > 1 else ''
            if prior == 'no':
                return 1.85  # no amount of
            if prior in {'any', 'some'}:
                return 0.8  # quantified amount of
    if lower in {'body', 'thing'} and prev in {'every', 'some', 'any', 'no'}:
        return -0.9  # split indefinite pronoun
    if word == 'หน':
        return -1.4  # Thai หน fragment
    if text == '··':
        return -0.49  # repeated middle dots
    if '一' in word:
        if word.startswith(('同一', '每一')):
            return 1.2  # same or every one in Chinese
        if word.startswith(('另一', '这一', '這一')):
            return 0.5  # other or this one in Chinese
        if word.startswith('一') and before.endswith(('每', '同', '任')):
            return 2.2  # Chinese one after each or same
        if word.startswith('一') and before.endswith(('上', '下', '前', '另', '单', '單')):
            return 0.35  # Chinese one after directional modifier
        if word.startswith('一') and len(word) > 1:
            return 0.1  # Chinese one compound
    return 0.0  # background


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    value = response(text, before, not before)
    return (doc, (before + text)[-256:]), value

"""Approximate formatting responses, not the component's lexical background.

Small character-shape offsets describe the background. Document starts have
separate baselines for digits, capital letters, and special markers. Stronger
rules recognize an initial NUL, title/issue headers, and unmatched square or
curly closers. A nearby parenthesis closed with ] or } gets a larger response,
especially for simple spans without quotes, escapes, or nested brackets.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', [])
    _, tail, stack = carry
    token = prefix.token_strings[-1]
    value = (0.001 - 0.0035 * token.startswith(' ')
             - 0.0044 * (not token.isascii())
             + 0.019 * ('}' in token) - 0.011 * ('_' in token))
    if not tail:
        value = -0.09 if token.strip().isdigit() else 0.06
        if len(token) == 1 and token.isascii() and token.isupper():
            value = -0.25
        elif token.startswith('<|'):
            value = -0.067
    if not tail and token == '\x00':
        value = 3.453
    elif not tail and token == '<':
        value = 0.237
    elif token == ':' and tail == 'Title':
        value = -1.566
    elif token == 'issue':
        if tail.endswith('<issue_start><'):
            value = 1.22
        elif tail == '<':
            value = 0.25
    elif token == '>Title' and tail.endswith('<issue_start><issue_comment'):
        value = -0.306
    elif token == ':' and tail.endswith('<issue_start><issue_comment>Title'):
        value = -0.10

    for char in token:
        if char in '([{':
            stack.append((char, prefix.position))
        elif char in ')]}':
            if stack:
                opener, position = stack.pop()
                if (opener == '(' and char in ']}'
                        and prefix.position - position <= 24):
                    span = ''.join(
                        prefix.token_strings[position:prefix.position])
                    simple = not any(c in span for c in '\\\n[]{}"\'')
                    if simple:
                        value = 0.55
                    else:
                        value = 0.20 if char == ']' else 0.08
            elif tail and char in ']}':
                value = 0.12 if char == ']' else 0.05
    return (doc, (tail + token)[-80:], stack), value

