"""Scientific-notation exponent detector for layers.1.mlp.down_proj component 2223.

The component is almost silent except inside numbers written in scientific notation, such as
`1e-7`, `6.6E-34` or `3e5`. There it writes a large negative value on the exponent marker
(`e` or `E`) and on its sign, and a smaller one on the first exponent digit. Everything else
is predicted as 0. Only the prefix is read (at most four tokens back), so it is causal.

Predicted values, by token:
  - `e` right after a bare number (digits and dots only, e.g. `1` in `1e-7`): -9 when the
    number follows an operator or bracket (`tol = 1e-6`), otherwise -5.
  - `E` right after a bare number: -3.
  - `e` / `E` right after a mixed token (hash-like `3fa2e7`, `S13E`): -1.5 / -1.
  - `-` or `+` right after that marker: -12 after a bare number, -7 after a mixed one.
  - first digit of the exponent, after `e` or after the sign: -6 after a bare number, -2.6 after
    a mixed one.
  - all other tokens: 0.
"""

READS = ()

DIGITS = set("0123456789")
WORD_CHARS = set("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ._")
BEFORE_BARE_NUMBER = ("=", "*", "(", ")*", "×", "^", "+", ":")


def _ends_in_digit(token):
    return len(token) > 0 and token[-1] in DIGITS


def _number_ending_at(s, end):
    """(is the number plain digits and dots, the token before it, its length in tokens)."""
    text, j = "", end
    while j >= 0 and s[j] and set(s[j]) <= WORD_CHARS and len(text) < 24:
        text = s[j] + text
        j -= 1
    before = s[j] if j >= 0 else ""
    plain = set(text) <= DIGITS | {"."}
    return plain, before, len(text)


def _marker_value(s, end, plain_strong, plain_weak, mixed):
    """Value at an exponent marker whose number ends at token s[end]."""
    plain, before, length = _number_ending_at(s, end)
    if not plain:
        return mixed
    if before in BEFORE_BARE_NUMBER:
        return plain_strong
    return plain_weak


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    prev = s[-2] if len(s) > 1 else ""
    prev2 = s[-3] if len(s) > 2 else ""
    prev3 = s[-4] if len(s) > 3 else ""
    if cur == "e" and _ends_in_digit(prev):
        return None, _marker_value(s, len(s) - 2, -9.0, -5.0, -1.5)
    if cur == "E" and _ends_in_digit(prev):
        return None, _marker_value(s, len(s) - 2, -3.0, -3.0, -1.0)
    if cur in ("-", "+") and prev in ("e", "E") and _ends_in_digit(prev2):
        plain, _, _ = _number_ending_at(s, len(s) - 3)
        return None, (-12.0 if plain else -7.0)
    if cur.isdigit():
        if prev in ("e", "E") and _ends_in_digit(prev2):
            plain, _, _ = _number_ending_at(s, len(s) - 3)
            return None, (-6.0 if plain else -2.6)
        if prev in ("-", "+") and prev2 in ("e", "E") and _ends_in_digit(prev3):
            plain, _, _ = _number_ending_at(s, len(s) - 4)
            return None, (-6.0 if plain else -2.6)
    return None, 0.0

