"""A sparse orthographic detector, not a general semantic feature.

The strongest rules are epsilon followed by Greek sigma, Korean 'and/while'
endings, and Chinese/Japanese counters for discrete objects. Other text is
mostly quiet. Accents and whether sigma ends the word change its strength.
Leading carriage-return runs and an initial empty comment line are negative.
Coefficients are rounded estimates from training examples.
"""
import unicodedata

READS = ()

# Counters: flat pieces, small round things, and individual trees/plants.
COUNTERS = {'枚': 4.8, '颗': 5.6, '顆': 5.0, '棵': 3.2}
# Korean connective endings (and/while), including forms of 'do' and 'be'.
CONNECTIVES = {
    '며': 6.3, '면서': 5.5,
    '하며': 7.8, '하면서': 6.6,
    '으며': 3.9, '이며': 3.9, '있으며': 1.7,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', True)
    _, tail, only_returns = carry
    before = tail.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    carry = (doc, (tail + raw)[-16:], only_returns and raw == b'\r')
    s = token.strip()

    if s in COUNTERS:
        value = COUNTERS[s]
        if s in ('颗', '顆'):
            value += -1.2 if before[-1:].isdigit() else 0.8
        return carry, value
    if len(s) == 2 and s[0] == '一' and s[1] in COUNTERS:
        value = COUNTERS[s[1]]
        return carry, value - (1.4 if s[1] != '棵' else 0.0)
    if s in CONNECTIVES:
        return carry, CONNECTIVES[s]
    if token == '서' and before.endswith('면'):
        return carry, 4.6  # The same Korean ending split across tokens.
    if s in ('ながら', 'しながら'):  # Japanese 'while doing'.
        return carry, 0.65
    if token == '\r' and only_returns:
        return carry, -2.0
    if not tail and token == '//\n':  # Empty comment opening a document.
        return carry, -5.6

    if token in ('σ', 'ς'):
        last = before[-1:]
        final = token == 'ς'
        if last in ('ε', 'Ε'):
            return carry, 2.4 if final else 4.8
        if last in ('έ', 'Έ'):
            return carry, 4.2 if final else 6.4
        decomposed = unicodedata.normalize('NFD', last)
        base = ''.join(c for c in decomposed
                       if not unicodedata.combining(c)).lower()
        if base == 'ε':  # Polytonic epsilon with a breathing mark.
            return carry, 3.8 if '\u0301' in decomposed else 1.2
        if before.endswith(('ει', 'εί')):
            return carry, 1.05 if final else 0.85
        if base == 'ο':
            return carry, -0.4 if final else 0.0
