Weak extra rules cover -ah/-yah name endings, document openings, and middle
dots. This is a partial approximation, not a general language classifier.
"""
import re
import regex
from wordfreq import zipf_frequency
from functools import lru_cache
READS = ()
HEBREW_WORDS = set('''
