    n = sum(c.isalpha() for c in letters)
    dense = sum(history)>=6
    root = current in PREFIXES and current and unfamiliar(current)
    evidence = bool(root and piece not in SUFFIXES)
    latin = bool(text and text.isascii() and text.isalpha())
    value = 0.0
    if n and not yiddish:
        value = -2.56 if n == 1 else -0.97
        if dense:
            value += 0.68
    if piece == 'hebrew':
        value -= 1.29
    elif piece in {'israel', 'israeli', 'israelis'}:
        value -= 1.42
    elif piece in {'jew', 'jews', 'jewish', 'judaism'}:
        value -= 0.24
    elif piece in {'rabbi', 'rabbis'}:
        value -= 1.30
    elif piece in {'blessing', 'blessings'}:
        value -= 0.83
    elif piece in {'holy', 'biblical', 'sabbath'}:
        value -= 0.21
    if evidence:
        value -= 0.54
        if topic > 0.2:
            value -= 3.06
        if len(piece) >= 3:
            value += 0.41
    if latin and old and piece.endswith(('ah', 'yah', 'yahu')):
        value -= 0.24
    if opening:
        value += 0.13
    if '··' in token:
        value += 0.70
    if current in CUES or current in HEBREW_WORDS or n:
        topic = 1.0
    if current == 'yiddish':
        yiddish = True
    if current == 'hebrew':
