def step(carry, prefix, upstream):
    return features(carry, prefix.token_strings[-1], prefix.document_ids[-1])

"""Approximate a tokenization-sensitive EAR-versus-AR spelling feature.

Short EAR families (dear, fear, gear, tear, etc.) respond positively, with
family-specific strengths and a few inflection adjustments. Isolated `ear`
and short e|ar completions are stronger. Longer unrelated words such as
linear, appear, clear and learning are not treated the same way. Unspaced
Latin AR fragments in the selected short forms receive a conservative
negative response, stronger after
an A vowel. A few corresponding Arabic/Cyrillic and Indic spelling rules,
and katakana e+a, extend the pattern beyond Latin script.

All other cases return zero. A short byte suffix reconstructs characters
split between tokens; this state resets at document boundaries. These are
spelling heuristics, not claims about the meanings of the words.
"""
import re
import unicodedata
import regex
from anyascii import anyascii

