# Onsets of short EAR spelling families: d+ear, sp+ear, and so on.
EAR_FAMILIES = {
    "": 3.8,
    "b": 1.4,
    "d": 4.0,
    "f": 3.0,
    "g": 3.8,
    "h": 0.7,
    "l": 2.0,
    "n": 1.3,
    "p": 3.5,
    "r": 2.7,
    "s": 3.0,
    "sh": 3.3,
    "sm": 1.3,
    "sp": 3.6,
    "t": 4.2,
    "w": 0.9,
}
INFLECTIONS = {"", "s", "d", "ed", "ing", "ings", "er", "ers"}


def response(token, before):
    word = token.strip()
    low = word.lower()
    spaced = token[:1].isspace()
    if not re.fullmatch('[a-zA-Z]+', word):
        return 0.0

    # Complete a short EAR family across a token seam, not an unrelated
    # long word such as line|ar or appe|ars, or a camel-case API name.
    if not spaced and before.lower().endswith('e') and low.startswith('ar'):
        previous = re.search('[a-zA-Z]+$', before)
        stem = previous[0][:-1].lower() if previous else ''
        for affix in ('over', 'under', 're', 'en'):
            if stem.startswith(affix) and stem[len(affix):] in EAR_FAMILIES:
                stem = stem[len(affix):]
                break
