            return 6.2 if not word.isupper() else 9.0
        if tail in {'ed', 'd', 'ds', 'm', 'est'}:
            return 5.3
        if tail in {'ing', 'er'}:
            return 4.1
        if tail in {'t', 'e', 'ch', 'n', 'th', 'den', 'k', 'se'}:
            return 2.5
        return 0.0

    if 'ear' in low:
        onset, tail = low.split('ear', 1)
        if onset in EAR_FAMILIES and tail in INFLECTIONS:
            value = EAR_FAMILIES[onset]
            if not onset:
                if not spaced and low == 'ear' and word.islower():
                    value = 4.9
                elif tail:
                    value = 2.4
            if tail == 'ed':
                value *= 0.75
            if onset == 'w' and tail == 'ing':
                value *= 0.4
            if onset == 'b' and tail in {'er', 'ers'}:
                value = 3.8
            if onset == 'h' and tail == 'ing':
                value = 1.1
            return value
        if low == 'rearr':
            return 1.9
        if low == 'early' and not spaced and before[-1:].lower() in {'p', 'd'}:
            return 2.5
        if low in {'pearl', 'pearls', 'weary'}:
            return 1.0
        return 0.0

    # Continuation fragments containing AR, rather than whole spaced words.
    if not spaced:
        if low in {'ar', 'ars', 'ark', 'arm', 'arn', 'arp', 'ari', 'ara'}:
            if before[-1:].lower() in 'fco' and before:
                return 0.4
            if not before[-1:].isalpha():
                return 0.0
            preceding_word = re.search('[a-zA-Z]+$', before)
            vowels = re.findall('[aeiou]', preceding_word[0].lower()) if preceding_word else []
            return -2.2 if vowels and vowels[-1] == 'a' else -0.65
        if low.endswith('ar') and len(low) <= 4:
            if re.search('[aeiou]', low[:-2]):
                return -2.0
        if low in {'aran', 'array', 'aram'}:
            return -1.0
    return 0.0


def foreign_response(token, before):
    """Related short spellings, confined to the appropriate alphabets."""
    if len(token) == 1 and before:
        name = unicodedata.name(token, '')
        previous_name = unicodedata.name(before[-1], '')
        if name.endswith('LETTER RA') and 'VOWEL SIGN AA' in previous_name:
            return -4.5
        if name == 'KATAKANA LETTER A' and 'KATAKANA' in previous_name:
            if anyascii(before[-1]).lower().endswith('e'):
                return 1.4
    if not regex.fullmatch(r'[\p{Script=Arabic}\p{Script=Cyrillic}]+', token):
        return 0.0
    current = anyascii(token).lower()
    preceding = anyascii(before[-12:]).lower()
    match = re.search('[a-z]+$', preceding)
    preceding_word = match[0] if match else ''
    if re.fullmatch('[a-z]{0,2}ar[a-z]?', current):
        if preceding_word.endswith('a') and not current.startswith('a'):
            return -4.0
        vowels = re.findall('[aeiou]', preceding_word)
        return -1.2 if vowels and vowels[-1] == 'a' else -0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        raw = b''
    else:
        raw = carry[1]
    before = raw.decode('utf-8', errors='ignore')
    raw += prefix.token_bytes[-1]
    after = raw.decode('utf-8', errors='ignore')
    token = after[len(before):]
    if token.isascii():
        value = response(token, before)
    else:
        value = foreign_response(token, before)
    if token.isascii() and value < 0:
        value *= 0.5  # AR's negative strength varies greatly with context.
    return (doc, raw[-96:]), value

