"""Ukrainian-text feature.

Inside documents written in Ukrainian (detected from the Ukrainian-only letters і ї є ґ
seen so far in the document, and not outweighed by Russian-only letters ы э ъ ё), the
component goes negative on Cyrillic word pieces: strongest on the start of a word
(a token with a leading space, such as " под" or " пов", which begins a longer word) and
on the apostrophe inside a Ukrainian word (пов'язання). Vowel-final and Latin/punctuation
tokens are only mildly negative. The standalone word " і" ("and") is slightly positive.
Two document-opening special cases: a "Title:" header and a line-break ("//\n") as the
very first token of a document both give large values."""
UKRAINIAN_LETTERS = set("іїєґІЇЄҐ")
RUSSIAN_LETTERS = set("ыэъёЫЭЪЁ")
VOWELS = set("аеиоуюяіїєАЕИОУЮЯІЇЄ")
APOSTROPHES = set("'’")

READS = ()


def _is_cyr(ch):
    return "Ѐ" <= ch <= "ӿ"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "n": 0, "uk": 0, "ru": 0, "prev": ""}
    prev = carry["prev"]
    carry["prev"] = tok
    carry["n"] += 1
    if carry["n"] == 1 and tok == "//\n":
        return carry, 11.5
    if carry["n"] == 2 and prev == "Title" and tok == ":":
        return carry, -12.35
    carry["uk"] += sum(c in UKRAINIAN_LETTERS for c in tok)
    carry["ru"] += sum(c in RUSSIAN_LETTERS for c in tok)
    if carry["uk"] < 1 or carry["uk"] <= carry["ru"]:
        return carry, 0.0  # not a Ukrainian document
    core = tok.strip()
    if core and all(c in APOSTROPHES for c in core):
        inside_word = bool(prev.strip()) and _is_cyr(prev.strip()[-1])
        return carry, (-6.0 if inside_word else -0.5)
    if not any(_is_cyr(c) for c in core):
        return carry, (-0.6 if tok.startswith(" ") else -0.2)
    if core == "і":
        return carry, (1.0 if tok.startswith(" ") else -0.5)
    if any(c in UKRAINIAN_LETTERS for c in core):
        return carry, -0.6
    ends_in_vowel = core[-1] in VOWELS
    if tok.startswith(" "):  # first piece of a word
        if len(core) >= 6:
            return carry, -1.5
        return carry, (-2.6 if ends_in_vowel else -3.5)
    if len(core) == 1:
        return carry, -1.0
    return carry, (-1.2 if ends_in_vowel else -2.0)  # later piece of a word

