VOWELS = 'aeou'
PAIR = re.compile('[iy][aeou]')
SUFFIX = re.compile(r'a(?:tions?|tive|ted|ting|ry|ries|rian|l|ns?|nts?|nces?)$')
ALPHABETS = {'LATIN', 'GREEK', 'CYRILLIC', 'KATAKANA'}


@lru_cache(maxsize=16384)
def spelling(raw):
    text = anyascii(raw).lower()
    script = ''
    for ch in raw:
        if ch.isalpha():
            script = unicodedata.name(ch, '').split(' ')[0]
            break
    pairs = list(PAIR.finditer(text))
    pair = pairs[-1] if pairs else None
    return text, script, (pair.group()[-1] if pair else ''), (
        len(text) - pair.end() if pair else 99)


