    text, script, vowel, distance = a
    prev, prev_script, prev_vowel, prev_distance = b
    older = c[0]
    if not text:
        return 0.0
    continuation = text[0].isalpha() or text[0] == '_'
    n, m = len(text.strip()), len(prev.strip())

    # The token immediately after an i/y--vowel boundary.
    if (continuation and prev[:1] in VOWELS and prev[:1]
            and older.endswith(('i', 'y')) and m <= 3):
        if n == 1:
            if m == 1:
                return -0.47 if script == 'LATIN' else -2.23
            return -0.69 if prev.startswith('a') else -0.19
        if m == 1:
            return -0.66 if script in ALPHABETS else -0.02
        return -0.18 if older.endswith('i') else -0.06

    # A vowel begins this fragment after an i or y in the previous one.
    if prev.endswith(('i', 'y')) and text[0] in VOWELS:
        if text[0] == 'a':
            if SUFFIX.fullmatch(text):
                return -0.71 if m <= 1 else -0.06
            return -0.97 if prev_script in ALPHABETS else -0.06
        if text[0] == 'o':
            return -0.45 if script in {'LATIN', 'GREEK', 'CYRILLIC'} else -0.09
        return -0.48 if prev.startswith('a') else -0.18

    # A recent ia/ie/io/iu (or y-vowel) spelling spills into this fragment.
    if continuation and prev_vowel and prev_distance <= 2:
        if n == 1:
