        if not body and len(s) == 1:
            value = {0: 0.05, 1: 0.05, 2: 0.12,
                     3: -0.03, 4: -0.08}.get(padding, 0.0)
        elif len(s) == 3:
            value = -0.015 if not body else -0.06
        elif not body and len(s) == 4:
            value = -0.06
    elif s.startswith('\t') and not s.strip():
        if s.count('\t') == 1 and s.count(' ') <= 5:
            value = -0.05 - 0.025 * s.count(' ')
    elif s == '\xa0':
        value = -0.05

    if '\n' in s:
        parts = (line + s).split('\n')
        previous, line = parts[-2], parts[-1]
        previous_tokens, line_tokens = line_tokens, 0
        if previous.lstrip().startswith('```'):
            diff = 'diff' in previous or 'patch' in previous
        elif re.match(r'^(diff |@@|--- |\+\+\+ )', previous):
            diff = True
    else:
        line, line_tokens = (line + s)[-2048:], line_tokens + 1
    return (doc, line, previous, line_tokens, previous_tokens, diff), float(value)

"""Approximate detector of 应 ('respond/should') and related syllable spellings.

The negative response is strongest for a separate character, especially when
its UTF-8 bytes are split across tokens. Compounds adjust its strength. The
Japanese form and some Korean, Vietnamese and Latin spellings also trigger.
Separate formatting effects cover initial indentation and doubled middle dots.
"""
READS = ()
FORMS = '应應応응'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail = b'' if start else carry[1]
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'replace')
    word = text.strip()
    before = tail.decode('utf-8', 'ignore')
    value = 0.0

    # A split character is recognized only once, when its last byte arrives.
    completed = ''
    for ch in FORMS:
        encoded = ch.encode('utf-8')
        for cut in (1, 2):
            if tail.endswith(encoded[:cut]) and raw == encoded[cut:]:
                completed = ch
                before = tail[:-cut].decode('utf-8', 'ignore')
    ch = completed or (word if len(word) == 1 and word in FORMS else '')
    previous = before[-1:]
    if ch:
        if ch == '応':
            value = -8.0
            if previous in ('対', '反'):
                value = -4.5
            elif previous == '一':
                value = -5.7
        elif ch == '응':
            value = -11.0 if completed else -5.0
            if previous == '적':
                value = -1.2
        else:
            value = -13.8 if completed and ch == '應' else -5.6
            # Chinese compounds: response, adaptation, correspondence, assent.
            if not completed:
                if previous in ('回', '適', '适', '因'):
                    value = -3.8
                elif previous in ('對', '对'):
                    value = -2.2
                elif previous == '答':
                    value = -9.2
    elif any(ch in word for ch in '应應応'):
        length = max(1, sum(c.isalpha() for c in word))
        # Obligation words ('should', 'ought') keep a larger response.
        if any(w in word for w in ('应该', '應該', '应当', '應當')):
            value = -3.2 if word.endswith(('该', '該', '当', '當')) else -2.1
        else:
            value = -1.9 / max(1, length - 1) ** 2
            if word.startswith(('反应', '反應', '响应', '響應', '应对', '應對')):
                value *= 0.4
    elif word == 'ứng':
        value = -4.3 if text.startswith(' ') else -1.8
    elif word == '영':
        value = -1.2 if text.startswith(' ') else -0.9
    elif word == 'Ying':
        value = -4.4
    elif word.lower() == 'ung' and text.startswith(' '):
        value = -1.7
    elif text == '··':
        value = -0.79

    if start and text:
        # Indentation ending one column before a four-column tab stop.
        if text.strip(' ') == '' and len(text) % 4 == 3:
            value = -max(0.65, 2.1 - 0.05 * len(text))
        elif text.strip('\t') == '':
            value = 0.85 / len(text) ** 0.5
    return (doc, (tail + raw)[-32:]), value

"""Sparse lexical responses to document openings and conversation markup.

At a document's first token, recognize code declarations, comment openers,
Markdown markers, and common question openers. A colon immediately after an
initial Title has a separate large response. Inside a document, distinguish
reasoning/tool delimiters and paired middle dots. There is also a small
positive bias for tokens continuing an unspaced ASCII word. These are spelling
rules, not a source-code or question parser.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = 0.13 if token.isalpha() else 0.03
        if token.startswith(' '):
            value = -0.01
        if token == '<|im_start|>':
            value = 0.12
        elif token and not token.strip('\r\n'):
            value = 0.25
        elif token == '#pragma':
            value = 1.46
        elif token == 'var':
            value = 1.33
        elif token == 'bool':
            value = 1.37
        elif token in {'class', 'function', 'const'}:
            value = 0.70
        elif token in {'int', 'char'}:
            value = 0.50
        elif token in {'What', 'When', 'Where', 'Why', 'Who', 'Which', 'How',
                       'Is', 'Are', 'Do', 'Does', 'Can', 'Could', 'Will',
                       'Would', 'Should', 'Have', 'Has'}:
            value = 0.50
        elif token in {'Q', 'Question'}:
            value = 0.65
        elif token in {'A', 'An'}:
            value = 0.36
        elif token == 'package':
            value = 0.29
        elif token in {'#define', '#ifndef', '#ifdef'}:
            value = 0.90
        elif token in {'**', '__'}:
            value = 1.10
        elif token and set(token) == {'#'}:
            value = 0.14 + 0.14 * min(len(token), 3)
        elif token.startswith(('/*', '"""')):
            value = 0.65
        elif token == '//\n':
            value = -0.92
        return (doc, token, 0), value
    _, previous, position = carry
    value = 0.001
    if (previous[-1:].isascii() and previous[-1:].isalpha()
            and token[:1].isascii() and token[:1].isalpha()):
        value = 0.014
    if token == '<think>':
        value = -0.24
    elif token in {'<tool_call>', '</tool_call>'}:
        value = 0.075
    elif token in {'<tool_response>', '</tool_response>'}:
        value = -0.055
    elif token == '··':
        value = 0.54
    if position == 0 and previous == 'Title' and token == ':':
        value = 4.16
    return (doc, token, position + 1), value

programs.haiku:
"""Candidate v3: document starts by first-token class, the 'Title:' spike, dotted filler, <think> tag."""

READS = ()


def start_value(tok):
    """Mean activation of a document's first token, by its class."""
    if tok.startswith(" "):
        return -0.02
    if tok[:1].isupper():
        return 0.19
    if any("一" <= c <= "鿿" for c in tok):
        return 0.23
    if tok[:1].islower():
        return 0.08
    return 0.1


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        k, prev = 0, ""
    else:
        k, prev = carry[1] + 1, carry[2]
    v = 0.0
    if k == 0:
        v = start_value(tok)
    elif k == 1 and prev == "Title" and tok == ":":
        v = 4.16
    if tok == "<think>":
        v = -0.24
    if tok == "··":
        v = 0.54
    return (doc, k, tok), v

programs.sol:
"""A coarse late-fragment signal for unfamiliar alphabetic words.

Track the alphabetic word-so-far and how many token pieces have formed it.
Predict almost zero before the third piece, or when the preceding piece has
little dictionary support. Otherwise predict a positive signal, strongest for
unfamiliar 7--11 letter runs. Their length and dictionary familiarity set its
size. This captures a broad tendency, not individual lexical preferences.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LATIN_LANGUAGES = ('es', 'fr', 'de', 'it', 'pt', 'nl', 'id', 'tr')
SCRIPT_LANGUAGES = (
    ('CYRILLIC', 'ru'),
    ('GREEK', 'el'),
    ('ARABIC', 'ar'),
)


@lru_cache(maxsize=65536)
def frequencies(text):
    """Use Latin-language tables, or Russian/Greek/Arabic for their scripts."""
    text = text.strip().lower()
    names = [unicodedata.name(c, '') for c in text]
    for script, language in SCRIPT_LANGUAGES:
        if any(script in name for name in names):
            frequency = zipf_frequency(text, language)
            return frequency, frequency
    english = zipf_frequency(text, 'en') if text else 0.0
    if text and all('LATIN' in name for name in names):
        other = max(zipf_frequency(text, lang) for lang in LATIN_LANGUAGES)
    else:
        other = 0.0
    return english, other


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        previous, word, pieces = '', '', 0
    else:
        _, previous, word, pieces = carry

    letters = re.search(r'[^\W\d_]+$', token)
    continuing = bool(
        token and previous and token[0].isalpha() and previous[-1].isalpha()
    )
    if letters is None:
        word, pieces = '', 0
    elif continuing and letters.start() == 0:
        word, pieces = (word + token)[-60:], pieces + 1
    else:
        word, pieces = letters.group(), 1
    state = (document, token, word, pieces)

    if pieces < 3:
        value = -0.003
    elif frequencies(previous)[1] <= 1.5:
        value = 0.006
    else:
        english, other = frequencies(word)
        if other > 1.8:
            value = 0.078
        elif len(word) <= 5:
            value = 0.057
        elif len(word) > 11:
            value = 0.127
        elif english > 2.0:
            value = 0.098
        elif len(word) == 6:
            value = 0.212
        else:
            value = 0.402
    return state, value
